from (values
  ('b893031a-9ea6-5a4b-ba73-3217557936e8', 'The intern added anatomy to the problem list after morning teaching.', 'After the teaching round, the intern listed the study of body structure among the problems.', '晨间带教后，实习医生把解剖学写进了问题列表。'),
  ('950dea91-1cc5-5ac9-8e69-adacd8f390b8', 'On the ward round the registrar paused so juniors could name the function.', 'During rounds the senior stopped and asked the juniors to name the special work done by an organ, tissue, or system.', '查房时，高年资住院医师停下来，让低年资医生说出功能。'),
  ('ed941421-40bb-5e70-aa6b-851954cc5ff6', 'The lecture slide highlighted the embryology next to a simpler neighboring term.', 'The classroom slide put the study of development before birth beside a plainer nearby word.', '课堂幻灯把胚胎学标在一个更浅的邻近词旁边。'),
  ('22cee538-8cc6-544f-ac1e-01ea7ece9dc0', 'A one-paragraph case opened by naming the nourishment before later findings.', 'The short case first named food and substances that keep the body alive and growing, then listed what came next.', '短病例开头先写出营养；滋养，再写后面的发现。'),
  ('b482e6f2-efbe-5833-9d0e-eb17e5ecce48', 'The textbook figure labels the histology beside the neighboring tissue.', 'The printed figure marks the microscopic study of tissues next to the nearby tissue.', '教材插图把组织学标在邻近组织旁边。'),
  ('db3101f6-8fb6-522c-a9d5-1bcc5a3cdcf5', 'In class the tutor pointed to the nutrient on the wall chart.', 'The tutor used the wall chart and pointed to a substance in food used for energy, growth, or repair.', '课堂上，老师指着墙上的图讲解营养素。'),
  ('2c657152-4eee-5907-a37d-1dd04d11cf8b', 'In the skills lab students had to identify the hematology on a model.', 'Lab practice asked students to find the study of blood and blood-forming organs on the model.', '技能实验室里，学生要在模型上认出血液学。'),
  ('d2ce616b-e1a5-525c-acbd-2bc1c07f7e30', 'The handover sheet kept the blood vessel on its own line.', 'The handover kept a tube that carries blood through the body on a separate line.', '交接单给血管单独留了一行。'),
  ('76ef7f9e-d57e-581d-aff2-fda8186dbc66', 'After history taking, the student wrote the immunology under current problems.', 'Once the history was finished, the student listed the study of host defense against infection with the current problems.', '问完病史后，学生把免疫学写在目前问题下面。'),
  ('f32a1ea0-9da7-59e4-9f96-f1a3164b8c38', 'The tutorial pair had to point to the cardiovascular system and say it aloud.', 'Each pair pointed to the heart and blood vessels working as one system and said the words out loud.', '小组课上，两人要指出心血管系统并大声读出来。'),
  ('93f73680-1afd-5d9d-b573-8a01acefe3fb', 'A labelled classroom slide showed the biology without extra commentary.', 'The teaching slide simply marked the study of living organisms and left the rest for discussion.', '一张带标注的课堂幻灯只标出生物学，没有再加解释。'),
  ('f25902eb-c80b-5018-ad41-6aaa76d3d05a', 'In the tutorial, each pair had to explain the cytology in one spoken sentence.', 'Tutorial pairs had to say the study of cells, often from smears out loud in a single sentence.', '小组课上，每两人要用一句话口头解释细胞学。'),
  ('d7fcb6b0-4b4f-5099-9e73-be8363de10e0', 'At the teaching conference the film was used to locate the artery.', 'The teaching meeting used the image so students could find a vessel that carries blood away from the heart.', '教学读片会上，用这张片子让学生找出动脉。'),
  ('47fb63ee-9042-556a-93a5-8a72b6b6fa4b', 'Night handover listed the physiology before the overnight plan.', 'The night team named the study of how the body functions first, then said what to do overnight.', '夜班交接时先提到生理学，再讲夜间计划。'),
  ('2cde9c6a-9fa5-5e26-8f76-cb303eb37539', 'The chapter margin lists the capillary with other core classroom words.', 'The side note groups the thinnest vessel where exchange occurs with the other must-know terms.', '章节页边把毛细血管和其他课堂核心词列在一起。'),
  ('7330e739-369c-5aac-94e0-d73580398975', 'Bedside teaching returned to the endocrinology whenever the finding came up.', 'At the bedside the teacher kept coming back to the study of hormones and endocrine glands when that finding appeared.', '床旁带教时，一碰到这个发现就会回到内分泌学。'),
  ('576ed17a-62ea-5961-bcb7-7f4ceda8b889', 'The case stem named the vein before asking what to do next.', 'The exam-style stem first named a vessel that returns blood toward the heart, then asked for the next step.', '病例题干先写出静脉，再问下一步怎么做。'),
  ('a545da83-f83e-5281-bd52-433425a74329', 'The tutor wrote the psychology on the board and circled the classroom sense.', 'On the board the tutor wrote the study of mind, emotion, and behavior and marked the classroom meaning.', '老师把心理学写在黑板上，并圈出课堂义。'),
  ('32e66a75-350c-5d50-92ca-1f7963b354d5', 'Students had to explain the lymphatic system in one plain sentence of their own.', 'Each student had to say the network of lymph vessels, nodes, and lymphoid organs in one ordinary sentence.', '学生要用自己的一句白话解释淋巴系统。'),
  ('3e26100b-dcf1-510d-9cf0-c8d006cc574f', 'The first chapter figure was a simple diagram of the skeletal system.', 'The opening figure was a plain diagram of the bones and joints that support the body.', '该章第一张图就是骨骼系统的简单示意图。'),
  ('28be2337-a5ac-51ef-b1ff-de4a1acebe98', 'On rounds the registrar asked for the everyday function of the lymph vessel.', 'On rounds the senior asked what a channel that carries lymph toward nodes and veins does in ordinary words.', '查房时，住院医师问淋巴管日常起什么作用。'),
  ('47703bfa-f416-58dd-a1f8-db1540958441', 'The textbook treats the muscular system as core vocabulary, not extra trivia.', 'The book treats the muscles that move the body and its parts as a must-know classroom term, not spare trivia.', '教材把肌肉系统当作核心课堂词，而不是附加冷知识。'),
  ('f0159d4a-5e0d-535f-baff-854633fa935d', 'The wall chart boxed the lymph nodes so students could find it quickly.', 'The wall chart put a box around small filters along lymph vessels that trap microbes and debris to make it easy to spot.', '墙上的图给淋巴结加了框，方便学生快速找到。'),
  ('0ceac31b-f431-564b-a72b-9610a16c67d0', 'The handover sheet kept the circulatory system on its own line.', 'The handover kept the system that moves blood around the body on a separate line.', '交接单给循环系统单独留了一行。'),
  ('f980da84-c6f0-59b3-8d4f-6f576b933023', 'The intern added spleen to the problem list after morning teaching.', 'After the teaching round, the intern listed the abdominal organ that filters blood and stores platelets among the problems.', '晨间带教后，实习医生把脾写进了问题列表。'),
  ('456b49d4-2607-5f76-ac7e-3db605922893', 'The tutorial pair had to point to the respiratory system and say it aloud.', 'Each pair pointed to the airways and lungs used for gas exchange and said the words out loud.', '小组课上，两人要指出呼吸系统并大声读出来。'),
  ('1bb4b060-5d6e-5661-aeda-fadc6e90b720', 'The protocol tells the nurse when to expel and when to wait for review.', 'The written steps say when staff should to force something out of the body or airway and when to wait.', '规程写明护士何时该排出，何时等复查。'),
  ('c3f06b40-0043-57a2-86da-78e2c707f4ea', 'The matching quiz asked students to pair the urinary system with its classroom gloss.', 'The matching quiz linked the kidneys and tracts that form and pass urine to its classroom gloss.', '配对测验要求把泌尿系统和课堂释义对上。'),
  ('15da4124-ba13-5fae-bf0e-c9791d59e36f', 'The teaching conference used one slide only for the carbon dioxide.', 'The conference reserved a whole slide for the gas produced by metabolism and exhaled.', '教学讨论会单独用一张幻灯讲二氧化碳。'),
  ('94639394-9b98-592f-b7c6-9d66a161b501', 'Her revision list put the endocrine system with two neighboring system terms.', 'The revision list grouped glands that secrete hormones into the blood with two nearby system terms.', '她的复习表把内分泌系统和两个邻近系统词放在一起。'),
  ('65b90c98-d523-5a96-a787-b8b630481db1', 'In the skills lab students had to identify the oxygen on a model.', 'Lab practice asked students to find the gas required for aerobic tissue metabolism on the model.', '技能实验室里，学生要在模型上认出氧气。'),
  ('415740b6-100b-5eb2-a1df-12b5ec37b0b4', 'A margin gloss repeats the reproductive system in smaller type beside the main paragraph.', 'The margin repeats organs used for producing offspring in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出生殖系统。'),
  ('ea4cff61-1b66-5ea5-bd83-ae007f102cd6', 'After history taking, the student wrote the larynx under current problems.', 'Once the history was finished, the student listed the voice box between pharynx and trachea with the current problems.', '问完病史后，学生把喉写在目前问题下面。'),
  ('acb6d0b6-3767-5a76-8211-c5f91cb1b8a3', 'The attending asked whether this really was the windpipe or a looser bedside word.', 'The consultant checked that the team meant the everyday name for the trachea, not a vaguer everyday word.', '主治医师追问：这里是不是气管，还是只是更松的床旁说法。'),
  ('8797db99-60b4-5720-867d-2d7b67039da1', 'After examination the sign was documented as principal.', 'Once the exam was done, the team wrote that the finding was chief or most important in a structure or function.', '查体结束后，记录把该体征写成主要的。'),
  ('901fff6b-6aaa-513d-a589-8b1e222f92b2', 'In the tutorial, each pair had to explain the esophagus in one spoken sentence.', 'Tutorial pairs had to say the muscular tube from pharynx to stomach out loud in a single sentence.', '小组课上，每两人要用一句话口头解释食管。'),
  ('6d5282ed-de72-56b3-ba80-d0b3fa92ed9e', 'At the teaching conference the film was used to locate the joint.', 'The teaching meeting used the image so students could find the junction where two or more bones meet.', '教学读片会上，用这张片子让学生找出关节。'),
  ('9e1fa9c0-c825-5b80-b696-9b37466f685d', 'Night handover listed the cartilage before the overnight plan.', 'The night team named flexible connective tissue covering joints and airways first, then said what to do overnight.', '夜班交接时先提到软骨，再讲夜间计划。'),
  ('aadcabab-a11a-5b72-8b33-da94a0326943', 'The protocol tells the nurse when to exhale and when to wait for review.', 'The written steps say when staff should to breathe air out of the lungs and when to wait.', '规程写明护士何时该呼出，何时等复查。'),
  ('e2b40ee4-e59e-5e47-b717-64daeb404100', 'The handover sheet kept the bone marrow on its own line.', 'The handover kept the soft tissue inside bones that makes blood cells on a separate line.', '交接单给骨髓单独留了一行。'),
  ('09ad3ff5-e80e-54e2-9eef-4e70dad68ab7', 'The case stem named the molecule before asking what to do next.', 'The exam-style stem first named the smallest unit of a chemical compound, then asked for the next step.', '病例题干先写出分子，再问下一步怎么做。'),
  ('b04a84e5-8296-5190-959a-22282d2eaf6b', 'The quiz asked which finding should be called cube-shaped.', 'The quiz wanted the finding that is honestly having the shape of a cube, as some short bones do.', '测验问：哪个发现才该写成立方形的。'),
  ('631546e0-8ed0-580f-a513-a604104ca099', 'The admission note placed the saliva among the early working problems.', 'The first ward note included the watery secretion of the salivary glands in the early problem list.', '入院记录把唾液写进了初步问题。'),
  ('14e90678-af03-5860-84ed-09de474ae820', 'The teaching lab slip called the result interior and left the numbers beside it.', 'The practice report labeled the result as on the inside of a body part or cavity and kept the numbers next to it.', '教学化验单把结果写成内部的，数字写在旁边。'),
  ('4af873b9-c9c2-5c1b-a589-9fec911a7004', 'In the anatomy lab a pin marked the enzyme on the demonstration specimen.', 'A lab pin showed where a protein catalyst of a biochemical reaction sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了酶。'),
  ('643f4fde-5978-58c0-8e9f-3de8e82f0653', 'A textbook margin note contrasts external with a weaker everyday adjective.', 'The margin sets this word, meaning on the outside of the body or an organ, against a weaker everyday adjective.', '教材页边把外部的和一个更弱的日常形容词对照。'),
  ('975737c1-5aa8-5d51-a3ba-0ce1a0687d67', 'Her revision card grouped the kidney with two nearby classroom terms.', 'The revision card put the paired organ that filters blood and makes urine together with two neighboring class words.', '她的复习卡把肾和两个邻近的课堂词放在一组。'),
  ('444abf28-cdc3-5429-8e94-9535ea7d8bfe', 'A margin gloss repeats the hinge joint in smaller type beside the main paragraph.', 'The margin repeats a joint that moves mainly in one plane, like the elbow in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出屈戌关节；铰链关节。'),
  ('8d2206ed-69c5-5c6d-9fe9-7b9c3b569064', 'The intern added urine to the problem list after morning teaching.', 'After the teaching round, the intern listed the fluid waste formed by the kidneys among the problems.', '晨间带教后，实习医生把尿液写进了问题列表。'),
  ('a4de3a29-a0a7-5568-80e5-eb8cec356bbb', 'The case note named the pivot joint before describing what happened next.', 'The note first named a joint that allows rotation around a long axis, then said what followed.', '病历先写出车轴关节；枢轴关节，再写接下来发生了什么。'),
  ('084b4490-bc99-560b-a57e-de1a96b74093', 'The lecture slide highlighted the ureter next to a simpler neighboring term.', 'The classroom slide put the tube that carries urine from kidney to bladder beside a plainer nearby word.', '课堂幻灯把输尿管标在一个更浅的邻近词旁边。'),
  ('ddde7e1b-54df-5ca0-b123-9163d4435f55', 'A one-paragraph case opened by naming the socket before later findings.', 'The short case first named a hollow that receives another bone or structure, then listed what came next.', '短病例开头先写出关节窝；槽，再写后面的发现。'),
  ('faee7d42-9ca7-5b91-aeca-0bfc780bf729', 'The textbook figure labels the urethra beside the neighboring tissue.', 'The printed figure marks the tube that carries urine out of the bladder next to the nearby tissue.', '教材插图把尿道标在邻近组织旁边。'),
  ('1c52f7d6-72ad-5762-8ddd-3a88c356b0a9', 'In class the tutor pointed to the skull on the wall chart.', 'The tutor used the wall chart and pointed to the bony case of the brain.', '课堂上，老师指着墙上的图讲解颅骨。'),
  ('20da377e-725d-520f-a68c-8b582b06890e', 'In the skills lab students had to identify the bile on a model.', 'Lab practice asked students to find the liver secretion that helps digest fat on the model.', '技能实验室里，学生要在模型上认出胆汁。'),
  ('d0c3ac98-af4a-5767-abab-d8d3252f01c8', 'The progress note mentioned the elbow in one plain line.', 'The ward note used one simple line to record the joint between the upper arm and the forearm.', '病程记录用一句平实的话写到了肘。'),
  ('25ed650e-e6e8-568a-b316-874df4a33e54', 'After history taking, the student wrote the gallbladder under current problems.', 'Once the history was finished, the student listed the sac that stores and concentrates bile with the current problems.', '问完病史后，学生把胆囊写在目前问题下面。'),
  ('1d26d2f5-fa15-526b-8cc0-ab128ef2fbf7', 'The attending asked whether this really was the breast or a looser bedside word.', 'The consultant checked that the team meant the mammary gland and overlying tissue, not a vaguer everyday word.', '主治医师追问：这里是不是乳房，还是只是更松的床旁说法。'),
  ('245064de-7a34-5fd2-82f8-cfef90e4bf14', 'A labelled classroom slide showed the sodium without extra commentary.', 'The teaching slide simply marked the main extracellular cation in body fluids and left the rest for discussion.', '一张带标注的课堂幻灯只标出钠，没有再加解释。'),
  ('62d25312-450d-5ded-b281-ea5d6eb17414', 'The matching quiz asked students to pair the hip joints with its classroom gloss.', 'The matching quiz linked the ball-and-socket joints between femur and pelvis to its classroom gloss.', '配对测验要求把髋关节和课堂释义对上。'),
  ('93051d36-6925-58aa-9180-f2400deb956b', 'At the teaching conference the film was used to locate the potassium.', 'The teaching meeting used the image so students could find the main intracellular cation in body fluids.', '教学读片会上，用这张片子让学生找出钾。'),
  ('930ed53a-69bb-5c90-8bd2-9866c7946822', 'Night handover listed the cushioning before the overnight plan.', 'The night team named soft tissue or cartilage that spreads load and shock first, then said what to do overnight.', '夜班交接时先提到衬垫；缓冲，再讲夜间计划。'),
  ('96980448-f127-54e7-9af7-55d6bfe6db08', 'The chapter margin lists the bladder with other core classroom words.', 'The side note groups the muscular sac that stores urine with the other must-know terms.', '章节页边把膀胱和其他课堂核心词列在一起。'),
  ('7b9a4f9f-b7fd-5e33-87c0-56fa03c62825', 'A margin gloss repeats the striated muscles in smaller type beside the main paragraph.', 'The margin repeats skeletal muscle with a striped microscopic pattern in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出横纹肌。'),
  ('c379d7c4-e1ea-5a98-9032-0754de86963d', 'The case stem named the pancreas before asking what to do next.', 'The exam-style stem first named the gland that makes digestive enzymes and insulin, then asked for the next step.', '病例题干先写出胰腺，再问下一步怎么做。'),
  ('c22f0e9c-33ce-521b-bd72-50b1dacf9dc8', 'The case note named the smooth muscles before describing what happened next.', 'The note first named involuntary muscle of viscera and vessels, then said what followed.', '病历先写出平滑肌，再写接下来发生了什么。'),
  ('e57b716a-00a6-5320-ac3c-e8a8d2a3b439', 'The admission note placed the hormone among the early working problems.', 'The first ward note included a chemical messenger carried in blood in the early problem list.', '入院记录把激素写进了初步问题。'),
  ('d55a354d-3cdf-5459-8ba3-b2cde6b157d6', 'The first chapter figure was a simple diagram of the voluntary muscles.', 'The opening figure was a plain diagram of muscles under conscious control.', '该章第一张图就是随意肌的简单示意图。'),
  ('1ae600dc-a5f5-5437-908c-ba5e9b36c45f', 'In the anatomy lab a pin marked the pituitary on the demonstration specimen.', 'A lab pin showed where the master endocrine gland at the base of the brain sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了脑垂体。'),
  ('aebfe54a-7986-5f57-aa4a-b276374d23bc', 'The printed handover sheet kept the thyroid on the first line.', 'The paper handover put the neck gland that sets metabolic rate at the top of the list.', '打印的交接单把甲状腺放在第一行。'),
  ('4c789b33-bd55-5f70-a064-74e39323fc13', 'Her revision card grouped the ovum with two nearby classroom terms.', 'The revision card put the female gamete together with two neighboring class words.', '她的复习卡把卵子和两个邻近的课堂词放在一组。'),
  ('876d9e85-1c85-51d4-bcb8-305ae9a73cec', 'The handover sheet kept the adrenal gland on its own line.', 'The handover kept the paired gland on each kidney that makes steroids and catecholamines on a separate line.', '交接单给肾上腺单独留了一行。'),
  ('3e8f1991-b131-5002-9a90-082d0d68c3ca', 'The intern added testis to the problem list after morning teaching.', 'After the teaching round, the intern listed the male gonad that makes sperm and testosterone among the problems.', '晨间带教后，实习医生把睾丸写进了问题列表。'),
  ('28cac965-2659-556c-86e0-cf7969a0d62e', 'On the ward round the registrar paused so juniors could name the cortisone.', 'During rounds the senior stopped and asked the juniors to name a glucocorticoid used as antiinflammatory therapy.', '查房时，高年资住院医师停下来，让低年资医生说出可的松。'),
  ('0ecfd2e4-866d-5516-a53f-7a3b07b44211', 'The lecture slide highlighted the ovary next to a simpler neighboring term.', 'The classroom slide put the female gonad that makes ova and sex hormones beside a plainer nearby word.', '课堂幻灯把卵巢标在一个更浅的邻近词旁边。'),
  ('af749b44-b4ab-513e-aad8-623cf35240d0', 'A one-paragraph case opened by naming the adrenaline before later findings.', 'The short case first named the adrenal medullary hormone of the stress response, then listed what came next.', '短病例开头先写出肾上腺素，再写后面的发现。'),
  ('b2293e47-02ca-5d98-9616-350b82d0fee6', 'The textbook figure labels the testosterone beside the neighboring tissue.', 'The printed figure marks the main male sex steroid next to the nearby tissue.', '教材插图把睾酮标在邻近组织旁边。'),
  ('3413e4ba-37ff-5599-a81b-e70302d6e083', 'In class the tutor pointed to the insulin on the wall chart.', 'The tutor used the wall chart and pointed to the pancreatic hormone that lowers blood glucose.', '课堂上，老师指着墙上的图讲解胰岛素。'),
  ('b9479b16-81ea-55cf-be37-344e52bee373', 'In the skills lab students had to identify the progesterone on a model.', 'Lab practice asked students to find the steroid that supports the secretory endometrium on the model.', '技能实验室里，学生要在模型上认出孕酮。'),
  ('69437c7a-c4f3-53e8-859b-46e6ff6bca86', 'The progress note mentioned the glucagon in one plain line.', 'The ward note used one simple line to record the pancreatic hormone that raises blood glucose.', '病程记录用一句平实的话写到了胰高血糖素。'),
  ('ec2208f8-2970-5cb1-8cc9-95e268389a95', 'After history taking, the student wrote the estrogen under current problems.', 'Once the history was finished, the student listed the main female sex steroid family with the current problems.', '问完病史后，学生把雌激素写在目前问题下面。'),
  ('2234d678-a9db-5766-ab2b-857b2e8840ea', 'The case note named the collar bone before describing what happened next.', 'The note first named the clavicle, linking sternum to scapula, then said what followed.', '病历先写出锁骨，再写接下来发生了什么。'),
  ('15e8f692-0961-522e-988b-fd783a39fa74', 'After examination the sign was documented as tactile.', 'Once the exam was done, the team wrote that the finding was relating to the sense of touch.', '查体结束后，记录把该体征写成触觉的。'),
  ('b8038a8f-6634-54a5-964f-b64cf03fc85f', 'The first chapter figure was a simple diagram of the spinal column.', 'The opening figure was a plain diagram of the stacked vertebrae from skull to pelvis.', '该章第一张图就是脊柱的简单示意图。'),
  ('1b4791f7-0a80-5bca-ade1-78f178a75266', 'The textbook warns not to write accessory unless the evidence actually fits.', 'The book says use this word only when the finding truly is assisting a main organ or structure.', '教材提醒：证据对得上时才能写附属的。'),
  ('cbc89eed-3f57-502f-936c-118aab45acaa', 'The textbook treats the spinal cord as core vocabulary, not extra trivia.', 'The book treats the nerve cord inside the vertebral canal as a must-know classroom term, not spare trivia.', '教材把脊髓当作核心课堂词，而不是附加冷知识。'),
  ('11bfd09d-38ad-52f3-952c-676c152c0f22', 'The chapter margin lists the pharynx with other core classroom words.', 'The side note groups the throat cavity shared by airway and foodway with the other must-know terms.', '章节页边把咽和其他课堂核心词列在一起。'),
  ('0dafc16a-b063-5ed5-bcb9-7e83ae795fb2', 'Bedside teaching returned to the sperm whenever the finding came up.', 'At the bedside the teacher kept coming back to the male gamete when that finding appeared.', '床旁带教时，一碰到这个发现就会回到精子。'),
  ('8dbfa2df-9d04-5e9a-9181-d8cf502c4383', 'The case stem named the pathology before asking what to do next.', 'The exam-style stem first named the study of disease and tissue change, then asked for the next step.', '病例题干先写出病理学，再问下一步怎么做。'),
  ('19160b3f-dafd-5bc3-8ff7-fb4c2075d814', 'The tutor wrote the stomatitis on the board and circled the classroom sense.', 'On the board the tutor wrote inflammation of the mouth lining and marked the classroom meaning.', '老师把口腔炎写在黑板上，并圈出课堂义。'),
  ('254f0833-1059-5418-9c94-9bf3913fc2a1', 'The admission note placed the pathogen among the early working problems.', 'The first ward note included a microbe that can cause disease in the early problem list.', '入院记录把病原体写进了初步问题。'),
  ('6a3f9080-429b-53b8-beca-cd588e015750', 'The classroom quiz asked students to recognise the prolapse from a short stem.', 'The quiz used a short stem and asked students to recognise downward displacement of an organ from its place.', '随堂测验用一小段题干，让学生认出脱垂。'),
  ('4f62bd26-f669-55fe-b0ae-573971f9494f', 'In the anatomy lab a pin marked the fungus on the demonstration specimen.', 'A lab pin showed where a yeast or mold that can infect tissue sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了真菌。'),
  ('8f1dbb0b-9d63-57f6-ab06-771d2ee07278', 'The printed handover sheet kept the malfunction on the first line.', 'The paper handover put failure of an organ or device to work normally at the top of the list.', '打印的交接单把功能失调放在第一行。'),
  ('87b0471d-6f2a-51d1-b29e-e289f7c9a766', 'Her revision card grouped the obesity with two nearby classroom terms.', 'The revision card put excess body fat that raises health risk together with two neighboring class words.', '她的复习卡把肥胖和两个邻近的课堂词放在一组。'),
  ('95546827-6efd-53da-ba66-ea460a6591ee', 'The consultant summary named the bacterium and then restated it in plain words.', 'The senior first said a prokaryotic microbe, some of which cause disease, then repeated the idea in everyday language.', '顾问医师先点出细菌，再用白话复述一遍。'),
  ('58a5ddce-6a07-5b49-ae95-373094ea29fa', 'The intern added malnutrition to the problem list after morning teaching.', 'After the teaching round, the intern listed poor nutrition from deficit, excess, or imbalance among the problems.', '晨间带教后，实习医生把营养不良写进了问题列表。'),
  ('4714e11f-134e-5129-a3fd-bb8c52a67b99', 'The tutor asked for hereditary rather than a looser bedside word.', 'The teacher wanted this exact word, meaning passed from parents through genes, not a vaguer bedside term.', '老师要求用这个词（遗传的），不要换成更松的床旁说法。'),
  ('e98eec69-3f61-57ad-a5ac-b8ea6985b801', 'The lecture slide highlighted the virus next to a simpler neighboring term.', 'The classroom slide put an obligate intracellular infectious particle beside a plainer nearby word.', '课堂幻灯把病毒标在一个更浅的邻近词旁边。'),
  ('0850aa96-53cc-5d7e-b981-b74abe0cbca7', 'The first chapter figure was a simple diagram of the mental retardation.', 'The opening figure was a plain diagram of an outdated classroom term for intellectual disability.', '该章第一张图就是智力障碍（旧称）的简单示意图。'),
  ('9685d8d7-71fb-5f99-833d-b43cafaae603', 'The textbook example shows clinicians diagnose only after enough evidence.', 'The book shows staff to name the illness after history, exam, and tests only when the evidence is enough.', '教材例子写：证据够了才诊断。'),
  ('73e88474-1504-58d1-9815-b9f1df14de25', 'In class the tutor pointed to the paralysis on the wall chart.', 'The tutor used the wall chart and pointed to loss of the ability to move a part of the body.', '课堂上，老师指着墙上的图讲解麻痹。'),
  ('ea6e2ce2-983e-5136-8522-35c7cb856a97', 'The wall chart boxed the venereal disease so students could find it quickly.', 'The wall chart put a box around an older name for a sexually transmitted infection to make it easy to spot.', '墙上的图给性病（旧称）加了框，方便学生快速找到。'),
  ('74f185c9-24a5-565d-9c01-b3fedcbc366e', 'The progress note mentioned the symptom in one plain line.', 'The ward note used one simple line to record a change the patient feels or reports.', '病程记录用一句平实的话写到了症状。'),
  ('e55cf90e-0225-53da-aab3-894e00344712', 'After history taking, the student wrote the hepatitis under current problems.', 'Once the history was finished, the student listed inflammation of the liver with the current problems.', '问完病史后，学生把肝炎写在目前问题下面。'),
  ('83db5b11-a477-5e9b-8e0f-bc057ac03bbc', 'The attending asked whether this really was the sign or a looser bedside word.', 'The consultant checked that the team meant an objective finding the examiner can detect, not a vaguer everyday word.', '主治医师追问：这里是不是体征，还是只是更松的床旁说法。'),
  ('83b7cf90-40f6-51f5-893f-52e7e234de85', 'A labelled classroom slide showed the colitis without extra commentary.', 'The teaching slide simply marked inflammation of the colon and left the rest for discussion.', '一张带标注的课堂幻灯只标出结肠炎，没有再加解释。'),
  ('a4a25f6b-7fd2-5d39-bb7d-6c1099f33bbf', 'The teaching lab slip called the result symptomatic and left the numbers beside it.', 'The practice report labeled the result as showing symptoms of a disease and kept the numbers next to it.', '教学化验单把结果写成有症状的，数字写在旁边。'),
  ('2420ed04-d872-5c0a-bf6a-cbbbdf8f5af2', 'At the teaching conference the film was used to locate the cholera.', 'The teaching meeting used the image so students could find an acute diarrheal infection usually from contaminated water.', '教学读片会上，用这张片子让学生找出霍乱。'),
  ('f7e9aa43-417e-5e9e-9a61-a0edaf4c5e65', 'A textbook margin note contrasts asymptomatic with a weaker everyday adjective.', 'The margin sets this word, meaning having no symptoms despite disease or carriage, against a weaker everyday adjective.', '教材页边把无症状的和一个更弱的日常形容词对照。'),
  ('c69ab796-18fc-5c5f-9786-b7ba2f38f7c3', 'At the bedside the tutor asked a junior to show the typhoid fever on the patient diagram.', 'By the bed the tutor asked a junior to show a systemic Salmonella infection with prolonged fever on the patient diagram.', '床旁，老师让低年资医生在患者示意图上指出伤寒。'),
  ('77c946a8-7574-5615-81c0-e7333d9d1b08', 'A margin gloss repeats the acute disease in smaller type beside the main paragraph.', 'The margin repeats an illness that starts quickly and runs a short course in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出急性病。'),
  ('05f8c18e-968a-5651-b879-85a0fd1c80b5', 'The case stem named the boils before asking what to do next.', 'The exam-style stem first named painful pus-filled skin abscesses of hair follicles, then asked for the next step.', '病例题干先写出疖，再问下一步怎么做。'),
  ('3f2066d4-daad-503e-a476-cdcaa25ec6fb', 'The case note named the chronic disease before describing what happened next.', 'The note first named an illness that lasts a long time or recurs, then said what followed.', '病历先写出慢性病，再写接下来发生了什么。'),
  ('9fd1ad3c-7d68-592a-a8e4-1e89b9e0a546', 'The admission note placed the pimples among the early working problems.', 'The first ward note included small raised inflammatory spots on the skin in the early problem list.', '入院记录把丘疹写进了初步问题。'),
  ('5fb8c59e-d180-5761-9a76-064ecc1e2e1a', 'The first chapter figure was a simple diagram of the subacute disease.', 'The opening figure was a plain diagram of an illness whose course sits between acute and chronic.', '该章第一张图就是亚急性病的简单示意图。'),
  ('59125199-a5c3-5018-80ce-17c323a9f29b', 'In the anatomy lab a pin marked the pus on the demonstration specimen.', 'A lab pin showed where thick infected fluid of dead cells and microbes sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了脓。'),
  ('aaaef3a8-ee68-5955-a79d-d64927fdedab', 'Her presentation stayed fatal from admission through the first night.', 'From admission to the first night, the picture remained able to cause death.', '从入院到第一夜，她的表现一直是致命的。'),
  ('fbb7bdaf-0ab0-5cfe-8189-766b9190b014', 'Her revision card grouped the abscess with two nearby classroom terms.', 'The revision card put a localized pocket of pus together with two neighboring class words.', '她的复习卡把脓肿和两个邻近的课堂词放在一组。'),
  ('b546f356-726d-5885-ba0e-0dac2c9fd3dc', 'The handover sheet kept the rheumatic fever on its own line.', 'The handover kept an inflammatory sequel of streptococcal infection on a separate line.', '交接单给风湿热单独留了一行。'),
  ('e193e3fb-bf9f-5aba-aaa8-4bfa2c62ad73', 'The intern added armpit to the problem list after morning teaching.', 'After the teaching round, the intern listed the axilla, a common site of lymph nodes among the problems.', '晨间带教后，实习医生把腋窝写进了问题列表。'),
  ('e9d37374-4d49-53af-931c-9d14b09e1b27', 'The quiz asked which finding should be called subarachnoid.', 'The quiz wanted the finding that is honestly beneath the arachnoid, as in subarachnoid space.', '测验问：哪个发现才该写成蛛网膜下的。'),
  ('5d55583e-8cfd-55b8-aaa6-956f1b170828', 'A short teaching note introduced the blood poisoning\sepsis before any later complications.', 'The teaching note named systemic infection with a harmful host response first, before later complications.', '短教学笔记先介绍败血症；脓毒症，再谈后续并发症。'),
  ('a35310d0-c984-5af3-b6cb-d03e982d4338', 'The matching quiz asked students to pair the epidemic disease with its classroom gloss.', 'The matching quiz linked a disease spreading widely through a population to its classroom gloss.', '配对测验要求把传染病和课堂释义对上。'),
  ('7b2276b6-a88e-51b3-b2e9-7d15258ae8dc', 'The textbook figure labels the phagocyte beside the neighboring tissue.', 'The printed figure marks a cell that engulfs microbes or debris next to the nearby tissue.', '教材插图把吞噬细胞标在邻近组织旁边。'),
  ('7b1058d7-5860-5f39-b49e-87951b22efc1', 'Her revision list put the endemic disease with two neighboring system terms.', 'The revision list grouped a disease constantly present in a defined region with two nearby system terms.', '她的复习表把地方病和两个邻近系统词放在一起。'),
  ('19a28132-ee6d-5ab3-8bd2-fe9fda92eaff', 'In the skills lab students had to identify the antigen on a model.', 'Lab practice asked students to find a molecule that can trigger an immune response on the model.', '技能实验室里，学生要在模型上认出抗原。'),
  ('53b4c2ef-c952-5565-906d-b397964eb9c8', 'A margin gloss repeats the airborne droplets in smaller type beside the main paragraph.', 'The margin repeats infection spread by respiratory droplets in the air in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出飞沫传播。'),
  ('223d1af5-4fec-5551-bd9e-269cefcf77a1', 'After history taking, the student wrote the antibody under current problems.', 'Once the history was finished, the student listed a protein that binds a specific antigen with the current problems.', '问完病史后，学生把抗体写在目前问题下面。'),
  ('96dafc9d-c251-58b2-b7d0-f055ba285093', 'The attending asked whether this really was the apnea or a looser bedside word.', 'The consultant checked that the team meant a pause in breathing, not a vaguer everyday word.', '主治医师追问：这里是不是呼吸暂停，还是只是更松的床旁说法。'),
  ('c5fbc03f-37fb-5f3f-abf4-75ff202a2ddb', 'A labelled classroom slide showed the immunoglobulin without extra commentary.', 'The teaching slide simply marked an antibody protein class such as IgG or IgM and left the rest for discussion.', '一张带标注的课堂幻灯只标出免疫球蛋白，没有再加解释。'),
  ('1a637491-acf8-569c-a831-af79b144d5f4', 'In the tutorial, each pair had to explain the atonia in one spoken sentence.', 'Tutorial pairs had to say loss of normal muscle tone out loud in a single sentence.', '小组课上，每两人要用一句话口头解释张力缺乏。'),
  ('b7029ae1-87d8-5c12-a754-4d6a8e55cd10', 'At the teaching conference the film was used to locate the opsonization.', 'The teaching meeting used the image so students could find coating of a microbe so phagocytes can ingest it.', '教学读片会上，用这张片子让学生找出调理作用。'),
  ('3383f36a-987c-5058-a462-fec9ee6b6947', 'Night handover listed the degeneration before the overnight plan.', 'The night team named deterioration of tissue structure or function first, then said what to do overnight.', '夜班交接时先提到退化，再讲夜间计划。'),
  ('53f0e2bd-b7ad-5599-a3c8-3d912093280f', 'The chapter margin lists the complement with other core classroom words.', 'The side note groups plasma proteins that help antibodies kill microbes with the other must-know terms.', '章节页边把补体和其他课堂核心词列在一起。'),
  ('cbbedb52-ad30-56ca-ac43-d94bfc894ead', 'The handover sheet kept the negative feedback control on its own line.', 'The handover kept a loop in which the product dampens its own production on a separate line.', '交接单给负反馈调节单独留了一行。'),
  ('eedf84a6-8053-5cad-97f0-449b9272287f', 'In the lab a pin and a tag marked the gastrointestinal tract on the model.', 'A lab pin and tag showed the digestive tube from mouth to anus on the model.', '实验室里，模型和标签标出了胃肠道。'),
  ('41ef16d5-325c-52ee-87b2-6cddf4cf1eff', 'The tutorial pair had to point to the cardiac sphincter and say it aloud.', 'Each pair pointed to the sphincter at the esophagus-stomach junction and said the words out loud.', '小组课上，两人要指出贲门括约肌并大声读出来。'),
  ('d6fe470c-2166-55b8-b126-af1b649bbc7a', 'The admission note placed the ingestion among the early working problems.', 'The first ward note included taking food, fluid, or a substance by mouth in the early problem list.', '入院记录把摄入写进了初步问题。'),
  ('614722e6-24b1-5157-b8ad-5451c71194ed', 'The matching quiz asked students to pair the pyloric sphincter with its classroom gloss.', 'The matching quiz linked the sphincter that controls emptying into the duodenum to its classroom gloss.', '配对测验要求把幽门括约肌和课堂释义对上。'),
  ('4c743913-c66f-5b31-9782-93048cef89e8', 'In the anatomy lab a pin marked the absorption on the demonstration specimen.', 'A lab pin showed where uptake of a substance across a membrane or mucosa sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了吸收。'),
  ('397cb072-d469-5b66-b50e-7ef7cd627271', 'A textbook margin note contrasts digestive with a weaker everyday adjective.', 'The margin sets this word, meaning relating to the breakdown and absorption of food, against a weaker everyday adjective.', '教材页边把消化的和一个更弱的日常形容词对照。'),
  ('299782c4-5ff5-5f4f-9d73-8036d5ab7ee1', 'Her revision card grouped the chyme with two nearby classroom terms.', 'The revision card put the semi-fluid mix of food and gastric juice together with two neighboring class words.', '她的复习卡把食糜和两个邻近的课堂词放在一组。'),
  ('29fb422b-093d-569a-adbd-5cc7b61b4d80', 'The consultant summary named the elimination and then restated it in plain words.', 'The senior first said removal of waste or a drug from the body, then repeated the idea in everyday language.', '顾问医师先点出排泄，再用白话复述一遍。'),
  ('f8920830-9cf0-5729-af71-f8d0893b9827', 'The intern added duodenum to the problem list after morning teaching.', 'After the teaching round, the intern listed the first part of the small intestine among the problems.', '晨间带教后，实习医生把十二指肠写进了问题列表。'),
  ('4b411cd7-fbb9-5e62-8e35-b6754625cf22', 'The case note named the oral cavity \buccal cavity before describing what happened next.', 'The note first named the mouth cavity, then said what followed.', '病历先写出口腔，再写接下来发生了什么。'),
  ('59db5a7b-13a9-5bb2-b5c6-081a266b1259', 'The lecture slide highlighted the jejunum next to a simpler neighboring term.', 'The classroom slide put the middle part of the small intestine beside a plainer nearby word.', '课堂幻灯把空肠标在一个更浅的邻近词旁边。'),
  ('995d5ce5-1c70-556a-86b3-f634a636d06e', 'A one-paragraph case opened by naming the palate before later findings.', 'The short case first named the roof of the mouth, then listed what came next.', '短病例开头先写出腭，再写后面的发现。'),
  ('71ba61d0-d9b9-5e78-8e55-8466d1dfd0d3', 'The textbook figure labels the ileum beside the neighboring tissue.', 'The printed figure marks the last part of the small intestine next to the nearby tissue.', '教材插图把回肠标在邻近组织旁边。'),
  ('f9a254c8-fce4-5e76-9192-17afe1320f0e', 'In class the tutor pointed to the chewing on the wall chart.', 'The tutor used the wall chart and pointed to the act of grinding food with the teeth.', '课堂上，老师指着墙上的图讲解咀嚼。'),
  ('c4c10f8f-4231-509d-901c-ae00c36f8862', 'In the skills lab students had to identify the cecum on a model.', 'Lab practice asked students to find the pouch at the start of the large intestine on the model.', '技能实验室里，学生要在模型上认出盲肠。'),
  ('f4bcbc91-2ca4-5b70-8389-38ddfb28de50', 'The progress note mentioned the swallowing in one plain line.', 'The ward note used one simple line to record the act of moving a bolus from mouth toward the esophagus.', '病程记录用一句平实的话写到了吞咽。'),
  ('c6948c58-39bc-5607-b1ea-017094d48d83', 'After history taking, the student wrote the rectum under current problems.', 'Once the history was finished, the student listed the distal large bowel that stores feces with the current problems.', '问完病史后，学生把直肠写在目前问题下面。'),
  ('85c3de91-f41c-568a-aac6-c3be736d4c0a', 'The attending asked whether this really was the incisor or a looser bedside word.', 'The consultant checked that the team meant a front cutting tooth, not a vaguer everyday word.', '主治医师追问：这里是不是切牙；门齿，还是只是更松的床旁说法。'),
  ('d817d195-ce1c-542b-8b7f-eba7b1659277', 'A labelled classroom slide showed the colon without extra commentary.', 'The teaching slide simply marked the large intestine that absorbs water and forms stool and left the rest for discussion.', '一张带标注的课堂幻灯只标出结肠，没有再加解释。'),
  ('64a5b096-6291-5943-a99b-89bd36ffe3ce', 'In the tutorial, each pair had to explain the cuspid in one spoken sentence.', 'Tutorial pairs had to say a canine tooth out loud in a single sentence.', '小组课上，每两人要用一句话口头解释尖牙。'),
  ('982c3af0-b056-5ef9-be5b-e95925346d28', 'The teaching conference used one slide only for the sigmoid colon.', 'The conference reserved a whole slide for the S-shaped colon before the rectum.', '教学讨论会单独用一张幻灯讲乙状结肠。'),
  ('a5cad280-38a3-56d0-a9df-dc5c124d61f7', 'Her revision list put the ileocecal valve with two neighboring system terms.', 'The revision list grouped the valve between ileum and cecum with two nearby system terms.', '她的复习表把回盲瓣和两个邻近系统词放在一起。'),
  ('a3b33a10-6914-578b-b315-77b3f94b34f0', 'The chapter margin lists the molar with other core classroom words.', 'The side note groups a back grinding tooth with the other must-know terms.', '章节页边把磨牙和其他课堂核心词列在一起。'),
  ('d1460a52-952b-5f69-abca-0702c69cb990', 'A margin gloss repeats the ascending colon in smaller type beside the main paragraph.', 'The margin repeats the colon running up the right abdomen in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出升结肠。'),
  ('51fa62c7-14a4-54da-a309-823bdb406f1a', 'The case stem named the cementum before asking what to do next.', 'The exam-style stem first named the bony layer covering a tooth root, then asked for the next step.', '病例题干先写出牙骨质，再问下一步怎么做。'),
  ('54a44603-f78e-585b-b86a-4aa36e86858e', 'The case note named the transverse colon before describing what happened next.', 'The note first named the colon crossing the upper abdomen, then said what followed.', '病历先写出横结肠，再写接下来发生了什么。'),
  ('0c0a8255-8da7-5f12-9323-5dd3ed097060', 'Students had to explain the descending colon in one plain sentence of their own.', 'Each student had to say the colon running down the left abdomen in one ordinary sentence.', '学生要用自己的一句白话解释降结肠。'),
  ('71482e35-4555-5b7e-b68c-2a0b7e07b8da', 'The classroom quiz asked students to recognise the appendix from a short stem.', 'The quiz used a short stem and asked students to recognise the blind tube attached to the cecum.', '随堂测验用一小段题干，让学生认出阑尾。'),
  ('9b4099a6-c911-5b8e-acb7-b55ab25dc9ca', 'In the anatomy lab a pin marked the pulp on the demonstration specimen.', 'A lab pin showed where the soft inner tissue of a tooth sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了牙髓。'),
  ('855c6dff-fb75-59b7-999a-dd21aa060344', 'The printed handover sheet kept the stool on the first line.', 'The paper handover put feces passed from the bowel at the top of the list.', '打印的交接单把粪便放在第一行。'),
  ('310f6de3-7c01-58c1-b0a6-2efa7ef207f3', 'Her revision card grouped the enamel with two nearby classroom terms.', 'The revision card put the hard outer covering of a tooth crown together with two neighboring class words.', '她的复习卡把牙釉质和两个邻近的课堂词放在一组。'),
  ('fc653c45-e629-587a-aff6-7168ef722ce9', 'The consultant summary named the anus and then restated it in plain words.', 'The senior first said the distal opening of the alimentary canal, then repeated the idea in everyday language.', '顾问医师先点出肛门，再用白话复述一遍。'),
  ('49954556-6a52-5a3f-bcee-b3a0e874221a', 'The intern added periodontium to the problem list after morning teaching.', 'After the teaching round, the intern listed the tissues that support a tooth in the jaw among the problems.', '晨间带教后，实习医生把牙周组织写进了问题列表。'),
  ('24a63387-b84b-5a25-8dc7-144ef6ba8c74', 'The tutorial pair had to point to the hydrochloric acid and say it aloud.', 'Each pair pointed to the strong acid secreted by gastric glands and said the words out loud.', '小组课上，两人要指出盐酸并大声读出来。'),
  ('0d5e8af5-ae85-51b5-8b7e-41b748f714ac', 'A short teaching note introduced the deciduous dentition before any later complications.', 'The teaching note named the primary set of teeth in children first, before later complications.', '短教学笔记先介绍乳牙列，再谈后续并发症。'),
  ('92123d43-e1b8-5bad-9e98-dac31b98e996', 'A one-paragraph case opened by naming the abdomen before later findings.', 'The short case first named the belly cavity below the diaphragm, then listed what came next.', '短病例开头先写出腹部，再写后面的发现。'),
  ('3910feab-2f41-5da0-a458-7dd704682729', 'The textbook figure labels the cholesterol beside the neighboring tissue.', 'The printed figure marks a sterol in membranes and steroid hormone synthesis next to the nearby tissue.', '教材插图把胆固醇标在邻近组织旁边。'),
  ('f9ca908e-2451-54ef-9269-5d2ac1851cfd', 'Her revision list put the permanent dentition with two neighboring system terms.', 'The revision list grouped the adult set of teeth with two nearby system terms.', '她的复习表把恒牙列和两个邻近系统词放在一起。'),
  ('fdf84963-50b0-5f01-8b63-79078aab0719', 'At the bedside the tutor asked a junior to show the bile pigment on the patient diagram.', 'By the bed the tutor asked a junior to show colored bile compounds such as bilirubin on the patient diagram.', '床旁，老师让低年资医生在患者示意图上指出胆汁色素。'),
  ('9d687ae4-f175-5939-8fda-73ae76ae59d7', 'A margin gloss repeats the lower jaw in smaller type beside the main paragraph.', 'The margin repeats the mandible in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出下颌。'),
  ('e8e6f33f-4a6f-572d-aaca-ca4de2137460', 'After history taking, the student wrote the bilirubin under current problems.', 'Once the history was finished, the student listed the bile pigment from heme breakdown with the current problems.', '问完病史后，学生把胆红素写在目前问题下面。'),
  ('06d135d0-41df-5bc7-9a48-4b33dee3002d', 'The attending asked whether this really was the papillae or a looser bedside word.', 'The consultant checked that the team meant small nipple-like projections, as on the tongue, not a vaguer everyday word.', '主治医师追问：这里是不是乳头，还是只是更松的床旁说法。'),
  ('03796181-8cdb-5330-91bb-a5c35f7a52a8', 'Students had to explain the blood protein in one plain sentence of their own.', 'Each student had to say proteins carried in plasma in one ordinary sentence.', '学生要用自己的一句白话解释血浆蛋白。'),
  ('ec257e74-fac3-5e7d-95a6-64a860aaf272', 'The first chapter figure was a simple diagram of the taste bud.', 'The opening figure was a plain diagram of a cluster of taste receptors on the tongue.', '该章第一张图就是味蕾的简单示意图。'),
  ('e7c3f843-5add-5acf-9c97-1b504d123b0c', 'At the teaching conference the film was used to locate the erythrocyte.', 'The teaching meeting used the image so students could find the red blood cell that carries oxygen.', '教学读片会上，用这张片子让学生找出红细胞。'),
  ('ebbb06d2-06e9-51db-90ea-57c9ff6b6244', 'Night handover listed the uvula before the overnight plan.', 'The night team named the small fleshy tag hanging from the soft palate first, then said what to do overnight.', '夜班交接时先提到腭垂；悬雍垂，再讲夜间计划。'),
  ('9f904af1-3e23-52b8-98bd-4ae829599ce8', 'The chapter margin lists the glycogen with other core classroom words.', 'The side note groups the storage polysaccharide of liver and muscle with the other must-know terms.', '章节页边把糖原和其他课堂核心词列在一起。'),
  ('d4771483-6e77-5373-9efe-8b9c80ac2c7c', 'The handover sheet kept the parotid gland on its own line.', 'The handover kept the large salivary gland in front of the ear on a separate line.', '交接单给腮腺单独留了一行。'),
  ('3a9bafd4-1139-5357-87cc-f33ab8559a45', 'The case stem named the cilia before asking what to do next.', 'The exam-style stem first named hair-like projections that move mucus or fluid, then asked for the next step.', '病例题干先写出纤毛，再问下一步怎么做。'),
  ('6f36cc44-ca74-5d94-8a3b-9812496a963b', 'The tutorial pair had to point to the submandibular gland and say it aloud.', 'Each pair pointed to a salivary gland under the mandible and said the words out loud.', '小组课上，两人要指出下颌下腺并大声读出来。'),
  ('8fb9f962-7894-5614-a271-90ae8ba505e8', 'The admission note placed the amylase among the early working problems.', 'The first ward note included an enzyme that digests starch in the early problem list.', '入院记录把淀粉酶写进了初步问题。'),
  ('bf804476-73ef-52d1-ad66-68498e08185a', 'The classroom quiz asked students to recognise the lipase from a short stem.', 'The quiz used a short stem and asked students to recognise an enzyme that digests fat.', '随堂测验用一小段题干，让学生认出脂肪酶。'),
  ('62bd7441-427e-502f-a980-4231a32bf45d', 'The teaching conference used one slide only for the hepatic duct.', 'The conference reserved a whole slide for a duct carrying bile from the liver.', '教学讨论会单独用一张幻灯讲肝管。'),
  ('d684b50a-7ea3-53d7-9e9e-bd8f14326493', 'The printed handover sheet kept the epiglottis on the first line.', 'The paper handover put the flap that covers the larynx during swallowing at the top of the list.', '打印的交接单把会厌放在第一行。'),
  ('220fc233-7db3-547d-8b4c-0db64f0bfe9a', 'At the bedside the tutor asked a junior to show the cystic duct on the patient diagram.', 'By the bed the tutor asked a junior to show the duct joining the gallbladder to the bile duct on the patient diagram.', '床旁，老师让低年资医生在患者示意图上指出胆囊管。'),
  ('af75ca92-6718-5c08-858d-7a562d0722ca', 'A margin gloss repeats the nasal cavity in smaller type beside the main paragraph.', 'The margin repeats the air space inside the nose in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出鼻腔。'),
  ('8038ad78-df7a-5a9c-9ef2-fa5bef44e03a', 'The lecture placed the common bile duct next to related classroom structures.', 'The lecture sat the duct that carries bile into the duodenum beside related classroom structures.', '讲课把胆总管放在相关课堂结构旁边。'),
  ('f887a275-61d8-53dc-bd01-1dce3620bd6b', 'On the ward round the registrar paused so juniors could name the peristalsis.', 'During rounds the senior stopped and asked the juniors to name wave-like muscle contraction that moves gut contents.', '查房时，高年资住院医师停下来，让低年资医生说出蠕动。'),
  ('7bdd4bc4-5dbc-5191-98d1-ae27c9cee63b', 'The lecture slide highlighted the detoxification next to a simpler neighboring term.', 'The classroom slide put the process of making a harmful substance less toxic beside a plainer nearby word.', '课堂幻灯把解毒标在一个更浅的邻近词旁边。'),
  ('e29bdd7e-067c-5938-a6ed-ca366e6673b6', 'A one-paragraph case opened by naming the fundus before later findings.', 'The short case first named the part of a hollow organ farthest from its opening, then listed what came next.', '短病例开头先写出底；底部，再写后面的发现。'),
  ('24fa9108-3014-56af-9f59-28aa34bbf2e7', 'The textbook figure labels the emulsification beside the neighboring tissue.', 'The printed figure marks breaking fat into tiny droplets so enzymes can act next to the nearby tissue.', '教材插图把乳化标在邻近组织旁边。'),
  ('8bce982e-f1a2-5753-9c9f-341c7d424085', 'In class the tutor pointed to the antrum on the wall chart.', 'The tutor used the wall chart and pointed to a cavity, such as the gastric antrum.', '课堂上，老师指着墙上的图讲解窦；腔。'),
  ('0f842892-9666-57f7-9761-6748629ee576', 'The wall chart boxed the bile acid so students could find it quickly.', 'The wall chart put a box around liver-made acids that help digest fat to make it easy to spot.', '墙上的图给胆汁酸加了框，方便学生快速找到。'),
  ('29228e77-661a-5a02-9e1f-a808269d6f5c', 'The progress note mentioned the gingivitis in one plain line.', 'The ward note used one simple line to record inflammation of the gums.', '病程记录用一句平实的话写到了牙龈炎。'),
  ('76c928ff-7642-5e2e-aeac-19e39a1f1a47', 'After history taking, the student wrote the laparoscope under current problems.', 'Once the history was finished, the student listed an instrument for looking into the peritoneal cavity with the current problems.', '问完病史后，学生把腹腔镜写在目前问题下面。'),
  ('755ab307-f1ab-5333-ba6f-259bb8547af3', 'The tutorial pair had to point to the peptic ulcer and say it aloud.', 'Each pair pointed to an ulcer of stomach or duodenum from acid injury and said the words out loud.', '小组课上，两人要指出消化性溃疡并大声读出来。'),
  ('bddb210c-a360-5b8a-b777-e91b5400d3a6', 'A labelled classroom slide showed the pancreatitis without extra commentary.', 'The teaching slide simply marked inflammation of the pancreas and left the rest for discussion.', '一张带标注的课堂幻灯只标出胰腺炎，没有再加解释。'),
  ('0f5bf9bd-40bf-54d7-88f7-fc7d89d64437', 'In the tutorial, each pair had to explain the vomiting in one spoken sentence.', 'Tutorial pairs had to say forceful expulsion of gastric contents through the mouth out loud in a single sentence.', '小组课上，每两人要用一句话口头解释呕吐。'),
  ('410669cc-c023-5f1f-9dff-a2004ada0a7e', 'The teaching conference used one slide only for the paralytic ileus.', 'The conference reserved a whole slide for bowel obstruction from lost peristalsis, not a mechanical block.', '教学讨论会单独用一张幻灯讲麻痹性肠梗阻。'),
  ('8e2d838f-1416-5c75-9c07-5d77caec0abb', 'Night handover listed the perforation before the overnight plan.', 'The night team named a hole through the wall of a hollow organ first, then said what to do overnight.', '夜班交接时先提到穿孔，再讲夜间计划。'),
  ('83336632-6e8f-5810-bb1d-96bbab704b42', 'The chapter margin lists the barium with other core classroom words.', 'The side note groups a radiopaque contrast used in GI imaging with the other must-know terms.', '章节页边把钡和其他课堂核心词列在一起。'),
  ('e45b8182-cb14-5d1f-babc-d9b6b8cc7d21', 'Bedside teaching returned to the autodigestion whenever the finding came up.', 'At the bedside the teacher kept coming back to tissue digested by its own enzymes, as in pancreatitis when that finding appeared.', '床旁带教时，一碰到这个发现就会回到自身消化。'),
  ('0f4137f1-3df5-5334-8d29-6ce0d7120a46', 'The note used hiatal to mark the quality of the finding.', 'The chart chose this adjective to say the finding was relating to a hiatus, especially the diaphragmatic hiatus.', '病历用这个词标明该发现是裂孔的。'),
  ('96101132-cb0f-58fa-a511-a0999c1ea36a', 'The tutor wrote the necrosis on the board and circled the classroom sense.', 'On the board the tutor wrote death of cells or tissue in a living body and marked the classroom meaning.', '老师把坏死写在黑板上，并圈出课堂义。'),
  ('b5133be2-4502-57e4-8869-5317708e6483', 'The admission note placed the hernia among the early working problems.', 'The first ward note included protrusion of a viscus through a weak wall in the early problem list.', '入院记录把疝写进了初步问题。'),
  ('2b900750-6bac-55c7-87b3-7be11d39c34b', 'The case stem described an epigastric change that students had to interpret.', 'The stem described a change that was in the upper central abdomen over the stomach and asked students to read it.', '题干写到一个上腹部的的改变，要学生自己判断。'),
  ('50de46a6-9d94-5d13-8316-bf4c3963aaee', 'In the anatomy lab a pin marked the endoscopy on the demonstration specimen.', 'A lab pin showed where inspection of a hollow organ with a lighted tube sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了内镜检查。'),
  ('fb89c984-2474-5be6-b26a-e0dfb9b20a02', 'The printed handover sheet kept the appendicitis on the first line.', 'The paper handover put inflammation of the appendix at the top of the list.', '打印的交接单把阑尾炎放在第一行。'),
  ('1b440205-58ca-59d2-81c8-916479f599f9', 'Her revision card grouped the hemorrhage with two nearby classroom terms.', 'The revision card put escape of blood from vessels together with two neighboring class words.', '她的复习卡把出血和两个邻近的课堂词放在一组。'),
  ('d5f2e043-537d-5a28-a777-91a949e63dbe', 'The consultant summary named the navel and then restated it in plain words.', 'The senior first said the umbilicus, then repeated the idea in everyday language.', '顾问医师先点出脐，再用白话复述一遍。'),
  ('bf9d2f89-4cec-5b65-a913-a69ad4d60566', 'The intern added histamine to the problem list after morning teaching.', 'After the teaching round, the intern listed a mediator of acid secretion and allergic inflammation among the problems.', '晨间带教后，实习医生把组胺写进了问题列表。'),
  ('cc4506bd-879b-54ac-8080-5733b0ddd82f', 'On the ward round the registrar paused so juniors could name the peritonitis.', 'During rounds the senior stopped and asked the juniors to name inflammation of the peritoneum.', '查房时，高年资住院医师停下来，让低年资医生说出腹膜炎。'),
  ('7f0c67b2-5012-5952-9ac1-c70e2236a31f', 'A short teaching note introduced the chest cavity before any later complications.', 'The teaching note named the thoracic cavity containing lungs and heart first, before later complications.', '短教学笔记先介绍胸腔，再谈后续并发症。'),
  ('8172cbe3-a32a-51ba-8146-d4f1ee00b87d', 'The matching quiz asked students to pair the ulcerative colitis with its classroom gloss.', 'The matching quiz linked chronic colonic mucosal inflammation with ulcers to its classroom gloss.', '配对测验要求把溃疡性结肠炎和课堂释义对上。'),
  ('0b892f69-8521-54e5-98e7-36c32797387a', 'The textbook figure labels the diaphragm beside the neighboring tissue.', 'The printed figure marks the main muscle of inspiration next to the nearby tissue.', '教材插图把膈标在邻近组织旁边。'),
  ('4cf9af8c-206d-50d9-8af5-83e192b214a0', 'In class the tutor pointed to the antibiotic on the wall chart.', 'The tutor used the wall chart and pointed to a drug used to treat bacterial infection.', '课堂上，老师指着墙上的图讲解抗生素。'),
  ('40671da1-ac7c-5116-a871-a5490951e8d6', 'In the skills lab students had to identify the gastritis on a model.', 'Lab practice asked students to find inflammation of the stomach lining on the model.', '技能实验室里，学生要在模型上认出胃炎。'),
  ('77725943-1e4c-5c13-a94b-c44dffdd6017', 'The progress note mentioned the fistula in one plain line.', 'The ward note used one simple line to record an abnormal tract between two epithelia or to the skin.', '病程记录用一句平实的话写到了瘘。'),
  ('bd096a46-038c-5219-9ba4-6103b4dc4992', 'After history taking, the student wrote the diverticulum under current problems.', 'Once the history was finished, the student listed a pouch bulging from a hollow organ wall with the current problems.', '问完病史后，学生把憩室写在目前问题下面。'),
  ('79dd8405-aed6-517e-a174-a676c3f88215', 'The attending asked whether this really was the cirrhosis or a looser bedside word.', 'The consultant checked that the team meant end-stage fibrosis and nodularity of the liver, not a vaguer everyday word.', '主治医师追问：这里是不是肝硬化，还是只是更松的床旁说法。'),
  ('8aecbf4f-db2e-5511-a5fd-778bcbbdb048', 'A labelled classroom slide showed the diverticulitis without extra commentary.', 'The teaching slide simply marked inflammation of a colonic diverticulum and left the rest for discussion.', '一张带标注的课堂幻灯只标出憩室炎，没有再加解释。'),
  ('36b04fee-4c33-58fb-a00a-2410c4f9d85d', 'In the tutorial, each pair had to explain the hepatomegaly in one spoken sentence.', 'Tutorial pairs had to say enlargement of the liver out loud in a single sentence.', '小组课上，每两人要用一句话口头解释肝肿大。'),
  ('10f99131-0544-5882-9403-b27aba9ac523', 'At the teaching conference the film was used to locate the diverticulosis.', 'The teaching meeting used the image so students could find presence of diverticula, usually in the colon.', '教学读片会上，用这张片子让学生找出憩室病。'),
  ('06d76ca6-7981-5701-8cc0-97d331f498b1', 'Night handover listed the edema before the overnight plan.', 'The night team named excess interstitial fluid in tissues first, then said what to do overnight.', '夜班交接时先提到水肿，再讲夜间计划。'),
  ('f55eab32-0d16-5d1a-8b2b-43b14f678444', 'The chapter margin lists the polyps with other core classroom words.', 'The side note groups abnormal mucosal growths, often in the bowel with the other must-know terms.', '章节页边把息肉和其他课堂核心词列在一起。'),
  ('9cafb3ca-493d-58ef-8c56-8c48424c9200', 'Bedside teaching returned to the jaundice whenever the finding came up.', 'At the bedside the teacher kept coming back to yellowing of skin or sclera from high bilirubin when that finding appeared.', '床旁带教时，一碰到这个发现就会回到黄疸。'),
  ('f6134232-b63b-5e0c-8125-e311d87435e7', 'The case stem named the diarrhea before asking what to do next.', 'The exam-style stem first named frequent passage of loose or watery stool, then asked for the next step.', '病例题干先写出腹泻，再问下一步怎么做。'),
  ('feebbebe-0fcc-5ec4-8534-ec19798ffb4f', 'The tutor wrote the architecture on the board and circled the classroom sense.', 'On the board the tutor wrote the organized microscopic arrangement of a tissue and marked the classroom meaning.', '老师把结构；构筑写在黑板上，并圈出课堂义。'),
  ('5bf1d9e0-d8ce-5009-ae74-83eee05eac18', 'A short teaching note introduced the occult blood before any later complications.', 'The teaching note named blood not visible to the eye, found by testing first, before later complications.', '短教学笔记先介绍隐血，再谈后续并发症。'),
  ('82c6617f-e254-551a-accc-3b96ca0ba789', 'The classroom quiz asked students to recognise the nodule from a short stem.', 'The quiz used a short stem and asked students to recognise a small firm lump in tissue.', '随堂测验用一小段题干，让学生认出结节。'),
  ('0e77e0c8-13b4-5776-ae98-da5956882376', 'In the anatomy lab a pin marked the proctoscope on the demonstration specimen.', 'A lab pin showed where an instrument for inspecting the rectum sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了直肠镜。'),
  ('9df25e21-8df5-5eb0-a6f2-7f9a27ac8fc5', 'A textbook margin note contrasts micronodular with a weaker everyday adjective.', 'The margin sets this word, meaning made of very small nodules, as in some cirrhosis, against a weaker everyday adjective.', '教材页边把小结节性的和一个更弱的日常形容词对照。'),
  ('8ca58d58-2699-576b-a1d9-aae9179223e1', 'Her revision card grouped the sigmoidoscope with two nearby classroom terms.', 'The revision card put an instrument for inspecting the sigmoid colon together with two neighboring class words.', '她的复习卡把乙状结肠镜和两个邻近的课堂词放在一组。'),
  ('17a41053-dbdb-5da8-bdf1-7467d2b644ed', 'Pair work asked when a finding is macronodular and when it is not.', 'Students had to say when a finding is made of large nodules and when that word is too strong.', '结对练习要分清：什么时候算大结节性的，什么时候还不算。'),
  ('b8f4ce83-7238-554d-a97e-9ec84f502388', 'The intern added colonoscope to the problem list after morning teaching.', 'After the teaching round, the intern listed an instrument for inspecting the whole colon among the problems.', '晨间带教后，实习医生把结肠镜写进了问题列表。'),
  ('98fb5c01-3ff9-566a-b9c7-2d3dcd11740f', 'The tutor asked for lobular rather than a looser bedside word.', 'The teacher wanted this exact word, meaning arranged in or relating to lobules, not a vaguer bedside term.', '老师要求用这个词（小叶的），不要换成更松的床旁说法。'),
  ('7fbdaf3f-0a5d-5ffa-99c5-e9a0380eb741', 'The lecture slide highlighted the ileostomy next to a simpler neighboring term.', 'The classroom slide put a surgical opening of ileum onto the abdominal wall beside a plainer nearby word.', '课堂幻灯把回肠造口术标在一个更浅的邻近词旁边。'),
  ('5f261d64-d7e8-5e02-8aa7-f0b39522d477', 'A one-paragraph case opened by naming the cholelithiasis before later findings.', 'The short case first named gallstones in the gallbladder or bile ducts, then listed what came next.', '短病例开头先写出胆石症，再写后面的发现。'),
  ('6975b1cd-7662-53b0-ba67-67faa1605ebe', 'The textbook figure labels the colostomy beside the neighboring tissue.', 'The printed figure marks a surgical opening of colon onto the abdominal wall next to the nearby tissue.', '教材插图把结肠造口术标在邻近组织旁边。'),
  ('cfbc2383-f9fe-5fd3-aaea-c838b8b9b4d7', 'In class the tutor pointed to the cholecystitis on the wall chart.', 'The tutor used the wall chart and pointed to inflammation of the gallbladder.', '课堂上，老师指着墙上的图讲解胆囊炎。'),
  ('7c900f71-537e-5c66-8b37-248aa66a6267', 'In the skills lab students had to identify the gastroduodenostomy on a model.', 'Lab practice asked students to find a surgical join between stomach and duodenum on the model.', '技能实验室里，学生要在模型上认出胃十二指肠吻合术。'),
  ('efcf44f0-7a25-5d8c-9802-2a8da5bb415e', 'The handover sheet kept the biliary colic on its own line.', 'The handover kept wave-like pain from a stone obstructing a bile duct on a separate line.', '交接单给胆绞痛单独留了一行。'),
  ('94f28abe-475c-5775-a6db-dcb7fa3969af', 'After history taking, the student wrote the nausea under current problems.', 'Once the history was finished, the student listed the unpleasant urge to vomit with the current problems.', '问完病史后，学生把恶心写在目前问题下面。'),
  ('17abf31f-02f8-55d6-8b49-285bcf5c5714', 'The attending asked whether this really was the coloproctostomy or a looser bedside word.', 'The consultant checked that the team meant a surgical join between colon and rectum, not a vaguer everyday word.', '主治医师追问：这里是不是结肠直肠吻合术，还是只是更松的床旁说法。'),
  ('a70bda5b-50bd-52ac-87d4-880fab4553b2', 'A labelled classroom slide showed the cholecystectomy without extra commentary.', 'The teaching slide simply marked surgical removal of the gallbladder and left the rest for discussion.', '一张带标注的课堂幻灯只标出胆囊切除术，没有再加解释。'),
  ('53756993-5dde-5d38-8f27-554a2d1a80a3', 'The matching quiz asked students to pair the pulmonary veins with its classroom gloss.', 'The matching quiz linked veins that return oxygenated blood from lungs to the left atrium to its classroom gloss.', '配对测验要求把肺静脉和课堂释义对上。'),
  ('f88b5766-a794-59db-a092-611a189ab66b', 'The teaching conference used one slide only for the maxillary sinus.', 'The conference reserved a whole slide for the paranasal sinus in the maxilla.', '教学讨论会单独用一张幻灯讲上颌窦。'),
  ('4ad0561b-9dd5-59d1-be5a-802332ed3410', 'Night handover listed the irritant before the overnight plan.', 'The night team named a substance that inflames or provokes a tissue first, then said what to do overnight.', '夜班交接时先提到刺激物，再讲夜间计划。'),
  ('d753d947-6f00-5c73-b949-8f947093acb2', 'At the bedside the tutor asked a junior to show the paranasal sinus on the patient diagram.', 'By the bed the tutor asked a junior to show an air sinus around the nasal cavity on the patient diagram.', '床旁，老师让低年资医生在患者示意图上指出鼻旁窦。'),
  ('72f68459-9d4e-5e35-850f-a5a62c14cdad', 'A margin gloss repeats the frontal sinus in smaller type beside the main paragraph.', 'The margin repeats the paranasal sinus in the frontal bone in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出额窦。'),
  ('acc859b9-4bc6-51a1-bf77-be1ca5a9d92a', 'The lecture placed the ethmoidal sinus next to related classroom structures.', 'The lecture sat the paranasal sinuses in the ethmoid beside related classroom structures.', '讲课把筛窦放在相关课堂结构旁边。'),
  ('b057d209-440d-5f70-8831-8562cbae41a6', 'The tutor wrote the nostril on the board and circled the classroom sense.', 'On the board the tutor wrote an external opening of the nose and marked the classroom meaning.', '老师把鼻孔写在黑板上，并圈出课堂义。'),
  ('7f1ae458-06e9-5ba2-ba3b-f06f097d7dbe', 'Students had to explain the sphenoid sinus in one plain sentence of their own.', 'Each student had to say the paranasal sinus in the sphenoid bone in one ordinary sentence.', '学生要用自己的一句白话解释蝶窦。'),
  ('72e598d3-053a-51e5-81db-a73bb26d2383', 'The classroom quiz asked students to recognise the nasopharynx from a short stem.', 'The quiz used a short stem and asked students to recognise the pharynx behind the nasal cavity.', '随堂测验用一小段题干，让学生认出鼻咽。'),
  ('80a11f2f-5c70-505f-a42e-6162f2cf38b2', 'In the anatomy lab a pin marked the oropharynx on the demonstration specimen.', 'A lab pin showed where the pharynx behind the oral cavity sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了口咽。'),
  ('0bad0dbe-2b7a-54b4-9223-8236c013e621', 'The printed handover sheet kept the apex on the first line.', 'The paper handover put the pointed end of an organ, such as the lung apex at the top of the list.', '打印的交接单把尖；顶端放在第一行。'),
  ('cd9ee2e2-e1e5-51f8-88b0-81268517263f', 'Her revision card grouped the hypopharynx with two nearby classroom terms.', 'The revision card put the lowest part of the pharynx; laryngopharynx together with two neighboring class words.', '她的复习卡把下咽和两个邻近的课堂词放在一组。'),
  ('a65c3fcc-e46d-5bdb-8342-cc27111f1312', 'The consultant summary named the hilum and then restated it in plain words.', 'The senior first said the site where vessels and bronchi enter an organ, then repeated the idea in everyday language.', '顾问医师先点出门，再用白话复述一遍。'),
  ('3dfaab4d-e66d-593d-b324-a3670a151b99', 'The intern added laryngopharynx to the problem list after morning teaching.', 'After the teaching round, the intern listed the pharynx beside the larynx among the problems.', '晨间带教后，实习医生把喉咽写进了问题列表。'),
  ('2dff758d-eb6d-5d92-9ba2-e2a6c6f2c1fd', 'On the ward round the registrar paused so juniors could name the collarbone.', 'During rounds the senior stopped and asked the juniors to name the clavicle.', '查房时，高年资住院医师停下来，让低年资医生说出锁骨。'),
  ('6b4a3bb7-dc79-5f2d-8b62-6c56c3c0e895', 'The lecture slide highlighted the adenoids next to a simpler neighboring term.', 'The classroom slide put pharyngeal tonsil tissue in the nasopharynx beside a plainer nearby word.', '课堂幻灯把腺样体标在一个更浅的邻近词旁边。'),
  ('4c3fcdec-3f12-534a-bdd6-5b54c524898c', 'The teaching lab slip called the result hypopharyngeal and left the numbers beside it.', 'The practice report labeled the result as relating to the hypopharynx and kept the numbers next to it.', '教学化验单把结果写成下咽的，数字写在旁边。'),
  ('58b2bd4f-805a-51cd-994b-a47beda81857', 'The textbook figure labels the mediastinum beside the neighboring tissue.', 'The printed figure marks the central chest compartment between the lungs next to the nearby tissue.', '教材插图把纵隔标在邻近组织旁边。'),
  ('f0918099-a3ae-5c93-9408-724e2c60005d', 'Her revision list put the pharyngeal tonsils with two neighboring system terms.', 'The revision list grouped lymphoid tissue in the nasopharynx; adenoids with two nearby system terms.', '她的复习表把咽扁桃体和两个邻近系统词放在一起。'),
  ('519da02a-ba3e-55ea-84f2-22fe9f8db0a3', 'At the bedside the tutor asked a junior to show the thoracic cavity on the patient diagram.', 'By the bed the tutor asked a junior to show the chest cavity enclosed by ribs and diaphragm on the patient diagram.', '床旁，老师让低年资医生在患者示意图上指出胸腔。'),
  ('ba686ee2-011b-5ed7-b80a-391c959b56b0', 'A margin gloss repeats the abdominal cavity in smaller type beside the main paragraph.', 'The margin repeats the peritoneal cavity of the abdomen in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出腹腔。'),
  ('b9f11f45-fe65-595d-89c4-c66faa321c31', 'The lecture placed the palatine tonsils next to related classroom structures.', 'The lecture sat the tonsils in the oropharynx beside related classroom structures.', '讲课把腭扁桃体放在相关课堂结构旁边。'),
  ('59cc42ab-70d4-5d53-aa3c-08b4c9a3c0b2', 'The attending asked whether this really was the inhalation or a looser bedside word.', 'The consultant checked that the team meant drawing air into the lungs, not a vaguer everyday word.', '主治医师追问：这里是不是吸气，还是只是更松的床旁说法。'),
  ('38dea84b-c519-5b49-a03d-bdf2ff661db7', 'Students had to explain the tongue tonsil in one plain sentence of their own.', 'Each student had to say lymphoid tissue at the tongue base; lingual tonsil in one ordinary sentence.', '学生要用自己的一句白话解释舌扁桃体。'),
  ('4a7375cd-a3ee-5176-a3bf-88d6c0ebb5b2', 'The first chapter figure was a simple diagram of the vocal cords.', 'The opening figure was a plain diagram of the folds in the larynx that produce voice.', '该章第一张图就是声带的简单示意图。'),
  ('358cc8ee-4bb1-5e73-a727-6711130f2cdc', 'At the teaching conference the film was used to locate the exhalation.', 'The teaching meeting used the image so students could find pushing air out of the lungs.', '教学读片会上，用这张片子让学生找出呼气。'),
  ('212bdf3d-c696-5bed-bd73-08d9047c0118', 'The textbook treats the mucous membrane as core vocabulary, not extra trivia.', 'The book treats a lining that secretes mucus as a must-know classroom term, not spare trivia.', '教材把黏膜当作核心课堂词，而不是附加冷知识。'),
  ('d0d8e833-b105-553e-bc46-b579006d02be', 'The chapter margin lists the brainstem with other core classroom words.', 'The side note groups the midbrain, pons, and medulla connecting brain to cord with the other must-know terms.', '章节页边把脑干和其他课堂核心词列在一起。'),
  ('4b95d2bd-97a2-56d1-897c-b17976dc2926', 'The handover sheet kept the fibrous connective tissue on its own line.', 'The handover kept dense connective tissue rich in collagen on a separate line.', '交接单给纤维结缔组织单独留了一行。'),
  ('b552d0a6-a5e6-5625-ad74-a7087cee5249', 'In the lab a pin and a tag marked the phrenic nerve on the model.', 'A lab pin and tag showed the nerve that drives the diaphragm on the model.', '实验室里，模型和标签标出了膈神经。'),
  ('2faee99d-e182-502a-8044-536ec531d07c', 'The tutor wrote the acid on the board and circled the classroom sense.', 'On the board the tutor wrote a proton donor that lowers pH and marked the classroom meaning.', '老师把酸写在黑板上，并圈出课堂义。'),
  ('b69a74d7-3095-5d06-8e84-4219ce9a2d74', 'The admission note placed the bronchi among the early working problems.', 'The first ward note included the two main airway branches from the trachea in the early problem list.', '入院记录把支气管写进了初步问题。'),
  ('5665add3-7291-5bf4-8077-1794dc38104f', 'The classroom quiz asked students to recognise the acidity from a short stem.', 'The quiz used a short stem and asked students to recognise how acidic a fluid or tissue is.', '随堂测验用一小段题干，让学生认出酸度。'),
  ('c75f43ff-031a-5190-8d2f-29fc3aed224e', 'In the anatomy lab a pin marked the bronchiole on the demonstration specimen.', 'A lab pin showed where a small airway distal to the bronchi sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了细支气管。'),
  ('6da3046f-5fe3-5f51-80b8-e8a65f7681b4', 'The printed handover sheet kept the acidosis on the first line.', 'The paper handover put a process that lowers blood pH or bicarbonate at the top of the list.', '打印的交接单把酸中毒放在第一行。'),
  ('f26eec7d-4b13-5cfd-9d40-f50f7e7d7af9', 'Her revision card grouped the alkalinity with two nearby classroom terms.', 'The revision card put how alkaline a fluid or tissue is together with two neighboring class words.', '她的复习卡把碱度和两个邻近的课堂词放在一组。'),
  ('9cf5c74c-0016-5afd-83cb-d9e0c1f9dd7e', 'The consultant summary named the alveoli and then restated it in plain words.', 'The senior first said the tiny air sacs where gas exchange occurs, then repeated the idea in everyday language.', '顾问医师先点出肺泡，再用白话复述一遍。'),
  ('b5607f0d-d9b5-5d73-b17a-09b05b2acfb5', 'The intern added alkali to the problem list after morning teaching.', 'After the teaching round, the intern listed a base that can neutralize acid among the problems.', '晨间带教后，实习医生把碱写进了问题列表。'),
  ('e9b01dd1-dbd9-598c-b54a-35c24fe04783', 'On the ward round the registrar paused so juniors could name the epithelium.', 'During rounds the senior stopped and asked the juniors to name the covering tissue of surfaces and glands.', '查房时，高年资住院医师停下来，让低年资医生说出上皮。'),
  ('58dbbb97-3af5-5ed0-9bbb-03e9d1bcce43', 'The lecture slide highlighted the alkalosis next to a simpler neighboring term.', 'The classroom slide put a process that raises blood pH or bicarbonate beside a plainer nearby word.', '课堂幻灯把碱中毒标在一个更浅的邻近词旁边。'),
  ('a3302b73-f9df-59af-8f4b-73db5ffd8515', 'The first chapter figure was a simple diagram of the parietal pleura.', 'The opening figure was a plain diagram of the pleural layer lining the chest wall.', '该章第一张图就是壁层胸膜的简单示意图。'),
  ('0a44a48b-7fed-54a1-9e5c-afc8014f52b7', 'The textbook figure labels the hyperventilation beside the neighboring tissue.', 'The printed figure marks breathing faster or deeper than metabolic need next to the nearby tissue.', '教材插图把过度通气标在邻近组织旁边。'),
  ('8fcafd4f-d893-5374-b2ce-ba417c39d24f', 'The textbook treats the visceral pleura as core vocabulary, not extra trivia.', 'The book treats the pleural layer covering the lung as a must-know classroom term, not spare trivia.', '教材把脏层胸膜当作核心课堂词，而不是附加冷知识。'),
  ('76d360d1-4523-59a9-a0f5-045412774832', 'In the skills lab students had to identify the hypoventilation on a model.', 'Lab practice asked students to find breathing too little for metabolic need on the model.', '技能实验室里，学生要在模型上认出通气不足。'),
  ('a2edff07-4ba4-55d8-bd75-b00531a85c6a', 'The handover sheet kept the horizontal fissure on its own line.', 'The handover kept the fissure separating the right upper and middle lobes on a separate line.', '交接单给水平裂单独留了一行。'),
  ('554bd88d-a49d-5c9f-a42b-d5f50290430b', 'After history taking, the student wrote the mucus under current problems.', 'Once the history was finished, the student listed the sticky secretion of mucous glands with the current problems.', '问完病史后，学生把黏液写在目前问题下面。'),
  ('9bde0500-f16d-58a0-847a-e586684d6e89', 'The tutorial pair had to point to the oblique fissure and say it aloud.', 'Each pair pointed to the fissure separating upper and lower lung lobes and said the words out loud.', '小组课上，两人要指出斜裂并大声读出来。'),
  ('2985b86e-51c0-50bb-b190-309f66158671', 'A labelled classroom slide showed the pneumonia without extra commentary.', 'The teaching slide simply marked infection of the lung parenchyma and left the rest for discussion.', '一张带标注的课堂幻灯只标出肺炎，没有再加解释。'),
  ('357d322b-d6c6-5e50-b4c4-0955e8562c4c', 'In the tutorial, each pair had to explain the exudates in one spoken sentence.', 'Tutorial pairs had to say protein-rich fluid leaking from inflamed vessels out loud in a single sentence.', '小组课上，每两人要用一句话口头解释渗出液。'),
  ('cfec0bab-2d96-5e58-be8c-826410840693', 'At the teaching conference the film was used to locate the tuberculosis.', 'The teaching meeting used the image so students could find infection with Mycobacterium tuberculosis.', '教学读片会上，用这张片子让学生找出结核病。'),
  ('e786feb0-573d-5252-aea8-b2250e5f5679', 'Night handover listed the solidification before the overnight plan.', 'The night team named lung tissue becoming firm, as in consolidation first, then said what to do overnight.', '夜班交接时先提到实变，再讲夜间计划。'),
  ('ff2a2715-f46a-5743-89c2-6fafb27eefdb', 'The chapter margin lists the asthma with other core classroom words.', 'The side note groups reversible airway obstruction with inflammation and spasm with the other must-know terms.', '章节页边把哮喘和其他课堂核心词列在一起。'),
  ('773150ad-2317-542d-8d08-5e3d8033779d', 'Bedside teaching returned to the consolidation whenever the finding came up.', 'At the bedside the teacher kept coming back to airless lung filled with exudate, as in pneumonia when that finding appeared.', '床旁带教时，一碰到这个发现就会回到实变。'),
  ('3a9942f3-5a64-56bd-b58f-5d83ff7574ab', 'The note used allergic to mark the quality of the finding.', 'The chart chose this adjective to say the finding was caused by or relating to allergy.', '病历用这个词标明该发现是过敏的。'),
  ('285d6a82-bd53-5824-8f64-f20e6bdd766d', 'The tutor wrote the dyspnea on the board and circled the classroom sense.', 'On the board the tutor wrote the sensation of difficult or labored breathing and marked the classroom meaning.', '老师把呼吸困难写在黑板上，并圈出课堂义。'),
  ('507ab76e-5159-5e4f-9332-c2a0e297bd0b', 'The admission note placed the emphysema among the early working problems.', 'The first ward note included destruction of alveolar walls with air trapping in the early problem list.', '入院记录把肺气肿写进了初步问题。'),
  ('82bb5ccb-2431-506d-a213-b1a9611036e1', 'The classroom quiz asked students to recognise the cyanosis from a short stem.', 'The quiz used a short stem and asked students to recognise bluish skin or mucosa from low oxygenated hemoglobin.', '随堂测验用一小段题干，让学生认出发绀。'),
  ('163e3c58-0f86-55a3-ad12-c10916add2e9', 'In the anatomy lab a pin marked the influenza on the demonstration specimen.', 'A lab pin showed where an acute viral respiratory infection sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了流行性感冒。'),
  ('d410e888-d482-5851-a4a2-afdf550b3b43', 'The printed handover sheet kept the wheeze on the first line.', 'The paper handover put a high-pitched whistling sound from narrowed airways at the top of the list.', '打印的交接单把哮鸣放在第一行。'),
  ('6df5da18-279e-5be9-b5fe-84353685aafb', 'Her revision card grouped the pneumonitis with two nearby classroom terms.', 'The revision card put inflammation of lung tissue, not always infectious together with two neighboring class words.', '她的复习卡把肺炎（广义）；肺炎症和两个邻近的课堂词放在一组。'),
  ('9dca5d3f-0040-5550-baae-fc07d55ee50b', 'The consultant summary named the steroids and then restated it in plain words.', 'The senior first said corticosteroid drugs that suppress inflammation, then repeated the idea in everyday language.', '顾问医师先点出甾体；糖皮质激素，再用白话复述一遍。'),
  ('0280771f-706f-536c-93bf-e18818636e1c', 'In the lab a pin and a tag marked the lobar pneumonia on the model.', 'A lab pin and tag showed pneumonia involving a whole lobe on the model.', '实验室里，模型和标签标出了大叶性肺炎。'),
  ('209c9ad2-f435-5e19-96c7-9cb30c9586f6', 'On the ward round the registrar paused so juniors could name the allergen.', 'During rounds the senior stopped and asked the juniors to name a substance that triggers allergy.', '查房时，高年资住院医师停下来，让低年资医生说出变应原。'),
  ('c8b10455-ab04-5f70-a918-2bdd241d5a20', 'The lecture slide highlighted the polio next to a simpler neighboring term.', 'The classroom slide put poliomyelitis, a viral disease that can paralyze beside a plainer nearby word.', '课堂幻灯把脊髓灰质炎标在一个更浅的邻近词旁边。'),
  ('41b3aab7-1fa0-508e-ba5f-08ac8e1d70e1', 'A one-paragraph case opened by naming the bronchopneumonia before later findings.', 'The short case first named patchy pneumonia centered on bronchioles, then listed what came next.', '短病例开头先写出支气管肺炎，再写后面的发现。'),
  ('681256b8-ff52-527e-82a8-f9f6dcefb4be', 'The textbook example shows clinicians paralyze only after enough evidence.', 'The book shows staff to take away the ability to move a part only when the evidence is enough.', '教材例子写：证据够了才使瘫痪。'),
  ('1af4e318-8985-5d15-82e9-c461fa28b6f8', 'In class the tutor pointed to the pleurisy on the wall chart.', 'The tutor used the wall chart and pointed to inflammation of the pleura, often painful.', '课堂上，老师指着墙上的图讲解胸膜炎。'),
  ('fe4fe13c-ee4e-591e-bb0e-24b14adec6d0', 'The registrar said the wording should stay mature in the discharge line.', 'The senior wanted the discharge line to keep the sense fully developed.', '住院总医师说出院小结仍应写成成熟的。'),
  ('bac3f4c6-150e-559f-81d3-d70630d03d32', 'The progress note mentioned the tubercle in one plain line.', 'The ward note used one simple line to record a small rounded nodule, classically in tuberculosis.', '病程记录用一句平实的话写到了结节；结核结节。'),
  ('98fc47bb-c7d1-516c-836c-fe0b17bf9725', 'The note used prematurely to mark the quality of the finding.', 'The chart chose this adjective to say the finding was earlier than the expected time.', '病历用这个词标明该发现是过早地。'),
  ('85707daf-d35e-5fd8-bd0f-34f8ad550777', 'The attending asked whether this really was the hemoptysis or a looser bedside word.', 'The consultant checked that the team meant coughing up blood from the lower airway, not a vaguer everyday word.', '主治医师追问：这里是不是咯血，还是只是更松的床旁说法。'),
  ('a50fc51a-0db7-591e-930d-6725d5b1854e', 'A labelled classroom slide showed the digitalis without extra commentary.', 'The teaching slide simply marked a cardiac glycoside used for some heart failure and arrhythmia and left the rest for discussion.', '一张带标注的课堂幻灯只标出洋地黄，没有再加解释。'),
  ('0d481607-939a-5ada-b668-3188aba96305', 'In the tutorial, each pair had to explain the phlegm in one spoken sentence.', 'Tutorial pairs had to say thick mucus from the airways out loud in a single sentence.', '小组课上，每两人要用一句话口头解释痰。'),
  ('8bc8de95-f1dd-5b87-9c92-73eafc77506d', 'At the teaching conference the film was used to locate the diuretics.', 'The teaching meeting used the image so students could find drugs that increase urine output.', '教学读片会上，用这张片子让学生找出利尿剂。'),
  ('f375a170-552b-5033-9190-c26c5a1332fb', 'Night handover listed the atrium before the overnight plan.', 'The night team named an upper receiving chamber of the heart first, then said what to do overnight.', '夜班交接时先提到心房，再讲夜间计划。'),
  ('493cceff-41b4-5e2d-9cf7-9c62e1bf3dfd', 'The chapter margin lists the bronchospasm with other core classroom words.', 'The side note groups sudden narrowing of bronchi by smooth-muscle contraction with the other must-know terms.', '章节页边把支气管痉挛和其他课堂核心词列在一起。'),
  ('50b2c540-c09e-5c37-ab1c-dbdb29693967', 'Bedside teaching returned to the hypercapnia whenever the finding came up.', 'At the bedside the teacher kept coming back to excess carbon dioxide in the blood when that finding appeared.', '床旁带教时，一碰到这个发现就会回到高碳酸血症。'),
  ('23b5415d-3686-5ddc-8dca-adbad78d56b7', 'In the lab a pin and a tag marked the simple chronic bronchitis on the model.', 'A lab pin and tag showed chronic bronchitis with cough and sputum but little obstruction on the model.', '实验室里，模型和标签标出了单纯慢性支气管炎。'),
  ('51ed92cf-e457-5c3c-9b20-f35d945d1bb2', 'The tutor wrote the pneumothorax on the board and circled the classroom sense.', 'On the board the tutor wrote air in the pleural space collapsing the lung and marked the classroom meaning.', '老师把气胸写在黑板上，并圈出课堂义。'),
  ('0d02c005-453b-5fed-9113-fb356a64051a', 'The admission note placed the pneumoconiosis among the early working problems.', 'The first ward note included lung disease from inhaled mineral dust in the early problem list.', '入院记录把尘肺写进了初步问题。'),
  ('ecd707b3-c6bc-5c10-a241-97d919575a71', 'The matching quiz asked students to pair the chronic obstructive bronchitis with its classroom gloss.', 'The matching quiz linked chronic bronchitis with airflow obstruction to its classroom gloss.', '配对测验要求把慢性阻塞性支气管炎和课堂释义对上。'),
  ('f332d63a-da1a-54eb-889e-cff341e98bf7', 'In the anatomy lab a pin marked the silicosis on the demonstration specimen.', 'A lab pin showed where pneumoconiosis from silica dust sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了矽肺。'),
  ('0e66c165-9b85-5f21-87fb-d84da6eb02a1', 'The printed handover sheet kept the anthracosilicosis on the first line.', 'The paper handover put pneumoconiosis from coal and silica dust at the top of the list.', '打印的交接单把煤矽肺放在第一行。'),
  ('bee5c646-fe6d-5045-994b-8a7a03c33eed', 'At the bedside the tutor asked a junior to show the asthmatic bronchitis on the patient diagram.', 'By the bed the tutor asked a junior to show bronchitis with a wheezing, reversible component on the patient diagram.', '床旁，老师让低年资医生在患者示意图上指出哮喘性支气管炎。'),
  ('3ea6e960-091d-56d2-a721-9f65a55e7ddf', 'The consultant summary named the bronchitis and then restated it in plain words.', 'The senior first said inflammation of the bronchi, then repeated the idea in everyday language.', '顾问医师先点出支气管炎，再用白话复述一遍。'),
  ('25b1228a-c3d1-5ed7-b892-0a242d77d8d5', 'The note used noxious to mark the quality of the finding.', 'The chart chose this adjective to say the finding was harmful to tissue or health.', '病历用这个词标明该发现是有害的。'),
  ('05ef2ce7-3e32-5221-987a-c80433d929b7', 'On the ward round the registrar paused so juniors could name the bronchiectasis.', 'During rounds the senior stopped and asked the juniors to name permanent abnormal widening of bronchi.', '查房时，高年资住院医师停下来，让低年资医生说出支气管扩张。'),
  ('8adeb74a-3d63-5232-ba9b-eb8b9f9af28f', 'The lecture slide highlighted the atherosclerosis next to a simpler neighboring term.', 'The classroom slide put plaque buildup that narrows arteries beside a plainer nearby word.', '课堂幻灯把动脉粥样硬化标在一个更浅的邻近词旁边。'),
  ('08d913bd-ff68-568d-b8cc-377d042c43d2', 'The first chapter figure was a simple diagram of the systolic pressure.', 'The opening figure was a plain diagram of the arterial pressure during ventricular contraction.', '该章第一张图就是收缩压的简单示意图。'),
  ('13fcbfd8-2d85-5ec1-8840-b6cd1824e451', 'On rounds the registrar asked for the everyday function of the diastolic pressure.', 'On rounds the senior asked what the arterial pressure during ventricular relaxation does in ordinary words.', '查房时，住院医师问舒张压日常起什么作用。'),
  ('190c163e-1d9e-51ba-a53f-9cecc2b93050', 'In class the tutor pointed to the lumen on the wall chart.', 'The tutor used the wall chart and pointed to the inner open space of a tubular organ.', '课堂上，老师指着墙上的图讲解管腔。'),
  ('f4db3cb4-8e7c-5f1f-8af4-a5a91aa9f74d', 'The wall chart boxed the congestive heart failure so students could find it quickly.', 'The wall chart put a box around heart failure with fluid backup in lungs or body to make it easy to spot.', '墙上的图给充血性心力衰竭加了框，方便学生快速找到。'),
  ('389f3f8f-93b4-5c3a-949c-7e43ccdbe784', 'The progress note mentioned the ischemia in one plain line.', 'The ward note used one simple line to record insufficient blood flow to a tissue.', '病程记录用一句平实的话写到了缺血。'),
  ('6b3c4179-0ca1-54c3-9046-2226edc15146', 'In the lab a pin and a tag marked the coronary heart disease on the model.', 'A lab pin and tag showed atherosclerotic disease of the coronary arteries on the model.', '实验室里，模型和标签标出了冠心病。'),
  ('733034a9-7cca-54ae-8054-1abb1bcdb17e', 'The attending asked whether this really was the vegetation or a looser bedside word.', 'The consultant checked that the team meant a clot-like mass on a valve, as in endocarditis, not a vaguer everyday word.', '主治医师追问：这里是不是赘生物，还是只是更松的床旁说法。'),
  ('c03dacf8-cc07-5998-9984-26aafedd8f44', 'A short teaching note introduced the angina pectoris before any later complications.', 'The teaching note named chest pain from myocardial ischemia first, before later complications.', '短教学笔记先介绍心绞痛，再谈后续并发症。'),
  ('2c8c556b-681e-5458-833a-4725b42d3ae5', 'The matching quiz asked students to pair the essential hypertension with its classroom gloss.', 'The matching quiz linked high blood pressure without an identified secondary cause to its classroom gloss.', '配对测验要求把原发性高血压和课堂释义对上。'),
  ('cae70a3f-1e92-5126-a218-360d105aeb1a', 'At the teaching conference the film was used to locate the clot.', 'The teaching meeting used the image so students could find a mass of coagulated blood.', '教学读片会上，用这张片子让学生找出血凝块。'),
  ('6c83e093-5cfa-528a-be11-549f63118fad', 'Night handover listed the thrombosis before the overnight plan.', 'The night team named formation of a clot inside a vessel first, then said what to do overnight.', '夜班交接时先提到血栓形成，再讲夜间计划。'),
  ('05fdff18-1a32-5908-91a5-8fd43e86dabb', 'At the bedside the tutor asked a junior to show the secondary hypertension on the patient diagram.', 'By the bed the tutor asked a junior to show high blood pressure caused by another disease on the patient diagram.', '床旁，老师让低年资医生在患者示意图上指出继发性高血压。'),
  ('f29e5812-643a-590e-8bd0-3c858106b81e', 'Bedside teaching returned to the thrombus whenever the finding came up.', 'At the bedside the teacher kept coming back to a clot formed in situ inside a vessel or heart when that finding appeared.', '床旁带教时，一碰到这个发现就会回到血栓。'),
  ('c8e730b6-4779-5f11-b902-4aa732251bf9', 'The lecture placed the myocardial infarction next to related classroom structures.', 'The lecture sat death of heart muscle from blocked coronary flow beside related classroom structures.', '讲课把心肌梗死放在相关课堂结构旁边。'),
  ('c5a07047-969a-5f3a-a0a2-d4d77b0b5c1f', 'The tutor wrote the endocarditis on the board and circled the classroom sense.', 'On the board the tutor wrote inflammation of the inner lining of the heart and marked the classroom meaning.', '老师把心内膜炎写在黑板上，并圈出课堂义。'),
  ('006b75de-2301-525a-a1ef-b8dc1d43d2b1', 'Students had to explain the pericardial tamponade in one plain sentence of their own.', 'Each student had to say compression of the heart by fluid in the pericardium in one ordinary sentence.', '学生要用自己的一句白话解释心包填塞。'),
  ('cb08b78c-4216-5860-9c2d-c5cf551272a6', 'The classroom quiz asked students to recognise the arhythmia from a short stem.', 'The quiz used a short stem and asked students to recognise an irregular heartbeat (textbook spelling of arrhythmia).', '随堂测验用一小段题干，让学生认出心律失常。'),
  ('8a91ca2d-f259-551b-bd8d-889ee726fb0b', 'In the anatomy lab a pin marked the fibrillation on the demonstration specimen.', 'A lab pin showed where rapid, uncoordinated muscle twitching, as in AF or VF sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了纤颤。'),
  ('876f2a7e-ba5c-5481-88a6-92f6964930ca', 'The printed handover sheet kept the pericarditis on the first line.', 'The paper handover put inflammation of the pericardium at the top of the list.', '打印的交接单把心包炎放在第一行。'),
  ('bde84ae1-ebd9-504c-951d-bb76c9010b8a', 'Her revision card grouped the embolism with two nearby classroom terms.', 'The revision card put blockage of a vessel by material carried in blood together with two neighboring class words.', '她的复习卡把栓塞和两个邻近的课堂词放在一组。'),
  ('4659d846-39ac-57d5-bf75-ab5df1f986ed', 'The consultant summary named the shock and then restated it in plain words.', 'The senior first said acute circulatory failure with inadequate tissue perfusion, then repeated the idea in everyday language.', '顾问医师先点出休克，再用白话复述一遍。'),
  ('49e5c51d-143b-5ef5-bd56-b941070d8771', 'The intern added embolus to the problem list after morning teaching.', 'After the teaching round, the intern listed intravascular material that travels and lodges downstream among the problems.', '晨间带教后，实习医生把栓子写进了问题列表。'),
  ('26582d53-0e0d-5c3a-bd15-fa49455b580a', 'On the ward round the registrar paused so juniors could name the plasma.', 'During rounds the senior stopped and asked the juniors to name the liquid part of unclotted blood.', '查房时，高年资住院医师停下来，让低年资医生说出血浆。'),
  ('58858b9e-fb64-5364-97f1-1a6b8f36e87a', 'The lecture slide highlighted the stroke next to a simpler neighboring term.', 'The classroom slide put sudden brain injury from ischemia or hemorrhage beside a plainer nearby word.', '课堂幻灯把卒中标在一个更浅的邻近词旁边。'),
  ('c97919f2-7220-5aa2-9e48-9b55aed74e14', 'A one-paragraph case opened by naming the dextran before later findings.', 'The short case first named a polysaccharide plasma expander, then listed what came next.', '短病例开头先写出右旋糖酐，再写后面的发现。'),
  ('575ba64d-cbe9-55c4-a38c-68b0c89816d0', 'During rounds the intern defended calling the course subcutaneous.', 'On rounds the intern explained why the course counted as beneath the skin, a common injection route.', '查房时，实习医生说明为什么病程可以写成皮下的。'),
  ('ebe7f837-a5ab-50a8-beff-2ae8cd1389f6', 'In class the tutor pointed to the vomitus on the wall chart.', 'The tutor used the wall chart and pointed to material ejected from the stomach.', '课堂上，老师指着墙上的图讲解呕吐物。'),
  ('44d59afa-8126-5bc9-8571-aa06941203dd', 'In the skills lab students had to identify the syncope on a model.', 'Lab practice asked students to find a brief loss of consciousness from hypoperfusion on the model.', '技能实验室里，学生要在模型上认出晕厥。'),
  ('b9f0e306-477e-561a-8c5e-16d95e39c64f', 'A margin gloss repeats the spermatic cord in smaller type beside the main paragraph.', 'The margin repeats the cord carrying vas, vessels, and nerves to the testis in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出精索。'),
  ('cf452a4f-e585-5ce0-972e-793beb922715', 'After history taking, the student wrote the glomerulonephritis under current problems.', 'Once the history was finished, the student listed inflammation of the glomeruli with the current problems.', '问完病史后，学生把肾小球肾炎写在目前问题下面。'),
  ('acf45d35-6d1d-58fb-962f-66be13d7f871', 'The attending asked whether this really was the ligament or a looser bedside word.', 'The consultant checked that the team meant the fibrous band that connects bone to bone, not a vaguer everyday word.', '主治医师追问：这里是不是韧带，还是只是更松的床旁说法。'),
  ('f1aa1ad1-fbce-5c8c-8c68-f4e1280b179e', 'A labelled classroom slide showed the pyelonephritis without extra commentary.', 'The teaching slide simply marked infection of the renal pelvis and kidney and left the rest for discussion.', '一张带标注的课堂幻灯只标出肾盂肾炎，没有再加解释。'),
  ('62dada54-2159-53b5-8149-9f0fc58893bc', 'In the tutorial, each pair had to explain the uterus in one spoken sentence.', 'Tutorial pairs had to say the organ that carries a pregnancy out loud in a single sentence.', '小组课上，每两人要用一句话口头解释子宫。'),
  ('6fcc5eb4-f2a7-5fe2-8e80-bcb951cd148f', 'On rounds the registrar asked for the everyday function of the rheumatic heart disease.', 'On rounds the senior asked what valve damage after rheumatic fever does in ordinary words.', '查房时，住院医师问风湿性心脏病日常起什么作用。'),
  ('009c6232-d43e-55b3-b5e8-6982ea7c3248', 'Night handover listed the piles before the overnight plan.', 'The night team named hemorrhoids first, then said what to do overnight.', '夜班交接时先提到痔，再讲夜间计划。'),
  ('668d5e3a-d1a1-540d-b568-41eab7d02166', 'The chapter margin lists the varix with other core classroom words.', 'The side note groups a permanently dilated vein with the other must-know terms.', '章节页边把静脉曲张和其他课堂核心词列在一起。'),
  ('87f636ad-058b-5208-9539-3ab2e2f330e7', 'The handover sheet kept the valvular murmur on its own line.', 'The handover kept a heart murmur from abnormal valve flow on a separate line.', '交接单给瓣膜杂音单独留了一行。'),
  ('a8cc902e-d818-5758-a7f7-9ab4c05c183d', 'The case stem named the phlebitis before asking what to do next.', 'The exam-style stem first named inflammation of a vein, then asked for the next step.', '病例题干先写出静脉炎，再问下一步怎么做。'),
  ('c8153d0b-ad43-5845-a431-b2ca7c413e5b', 'The tutor wrote the etiology on the board and circled the classroom sense.', 'On the board the tutor wrote the cause of a disease and marked the classroom meaning.', '老师把病因写在黑板上，并圈出课堂义。'),
  ('5ac4ce7b-3c1b-5bb7-8b08-37a20e231110', 'The admission note placed the hemocyte among the early working problems.', 'The first ward note included a blood cell in the early problem list.', '入院记录把血细胞写进了初步问题。'),
  ('d0c38449-1fe0-5456-8113-fe0b95578052', 'The classroom quiz asked students to recognise the leukocyte from a short stem.', 'The quiz used a short stem and asked students to recognise a white blood cell of host defense.', '随堂测验用一小段题干，让学生认出白细胞。'),
  ('934c32f4-4dfa-52d7-9aef-bf944c05a417', 'The teaching conference used one slide only for the thymus gland.', 'The conference reserved a whole slide for the gland where T lymphocytes mature.', '教学讨论会单独用一张幻灯讲胸腺。'),
  ('dc5c8f5c-2b95-5ea3-b6fe-4ddb9feaee68', 'The printed handover sheet kept the platelets on the first line.', 'The paper handover put cell fragments that help blood clot at the top of the list.', '打印的交接单把血小板放在第一行。'),
  ('7b42ed11-49ff-56cc-bfd9-b6cd535398af', 'At the bedside the tutor asked a junior to show the lymphoid organs on the patient diagram.', 'By the bed the tutor asked a junior to show organs of the immune system such as nodes and spleen on the patient diagram.', '床旁，老师让低年资医生在患者示意图上指出淋巴器官。'),
  ('89eff71c-a36e-5e9d-881f-6989e313ca60', 'The consultant summary named the thrombocytes and then restated it in plain words.', 'The senior first said another name for platelets, then repeated the idea in everyday language.', '顾问医师先点出血小板，再用白话复述一遍。'),
  ('26c887c4-1585-54fd-9191-3781971469e2', 'The intern added debris to the problem list after morning teaching.', 'After the teaching round, the intern listed broken-down tissue or foreign fragments among the problems.', '晨间带教后，实习医生把碎屑写进了问题列表。'),
  ('8476adeb-5e6c-5402-9170-676695d601aa', 'The case note named the clotting cells before describing what happened next.', 'The note first named cells or fragments that participate in clot formation, then said what followed.', '病历先写出凝血细胞，再写接下来发生了什么。'),
  ('137081b4-302a-5b28-b327-aea02789c5c3', 'After examination the sign was documented as cytotoxic.', 'Once the exam was done, the team wrote that the finding was able to kill cells.', '查体结束后，记录把该体征写成细胞毒性的。'),
  ('59fa516f-f800-51e0-9cc8-14eb3f8a7b4a', 'A one-paragraph case opened by naming the interferon before later findings.', 'The short case first named a cytokine that helps resist viral infection, then listed what came next.', '短病例开头先写出干扰素，再写后面的发现。'),
  ('cf17fcc4-8c29-5e03-91bd-463a76677c23', 'The textbook figure labels the fibrinogen beside the neighboring tissue.', 'The printed figure marks the plasma protein converted to fibrin in clotting next to the nearby tissue.', '教材插图把纤维蛋白原标在邻近组织旁边。'),
  ('71111b97-24d5-524e-8758-a8455abcbaed', 'In class the tutor pointed to the interleukins on the wall chart.', 'The tutor used the wall chart and pointed to cytokines that signal among white cells.', '课堂上，老师指着墙上的图讲解白细胞介素。'),
  ('4da77395-6aec-5aa8-958e-1fa71f7b133a', 'In the skills lab students had to identify the fibrin on a model.', 'Lab practice asked students to find the mesh protein that stabilizes a clot on the model.', '技能实验室里，学生要在模型上认出纤维蛋白。'),
  ('fce8a0a8-783d-554e-9e0a-9d2cde8cb38a', 'The progress note mentioned the anemia in one plain line.', 'The ward note used one simple line to record too little hemoglobin or too few red cells.', '病程记录用一句平实的话写到了贫血。'),
  ('0e9ea64d-b3ad-5df4-b9e5-85bc7d9ca397', 'After history taking, the student wrote the albumin under current problems.', 'Once the history was finished, the student listed the main plasma protein that maintains oncotic pressure with the current problems.', '问完病史后，学生把白蛋白写在目前问题下面。'),
  ('f076e1a3-4cfd-51b8-8fa4-1bef1d515e1f', 'The attending asked whether this really was the fatigue or a looser bedside word.', 'The consultant checked that the team meant tiredness not relieved by ordinary rest, not a vaguer everyday word.', '主治医师追问：这里是不是疲劳，还是只是更松的床旁说法。'),
  ('92b13e35-47f8-5c30-849a-7c93e27d3e03', 'A labelled classroom slide showed the globulin without extra commentary.', 'The teaching slide simply marked a class of plasma proteins including antibodies and left the rest for discussion.', '一张带标注的课堂幻灯只标出球蛋白，没有再加解释。'),
  ('cebda604-8734-578c-a874-6c0f66a74047', 'The matching quiz asked students to pair the heart palpitation with its classroom gloss.', 'The matching quiz linked awareness of an irregular or forceful heartbeat to its classroom gloss.', '配对测验要求把心悸和课堂释义对上。'),
  ('51f40c99-1c2a-510d-9112-b8b016816aac', 'At the teaching conference the film was used to locate the prothrombin.', 'The teaching meeting used the image so students could find a clotting factor converted to thrombin.', '教学读片会上，用这张片子让学生找出凝血酶原。'),
  ('415f00ce-3d36-50aa-a11f-b9766263198a', 'Night handover listed the pallor before the overnight plan.', 'The night team named paleness of skin or mucosa first, then said what to do overnight.', '夜班交接时先提到苍白，再讲夜间计划。'),
  ('17c23d3c-ddb4-5b0b-b246-898c40b17985', 'The chapter margin lists the globin with other core classroom words.', 'The side note groups the protein part of hemoglobin with the other must-know terms.', '章节页边把珠蛋白和其他课堂核心词列在一起。'),
  ('7c199358-2185-510f-8858-cc4285889f31', 'Bedside teaching returned to the irritation whenever the finding came up.', 'At the bedside the teacher kept coming back to local inflammation or unpleasant stimulation when that finding appeared.', '床旁带教时，一碰到这个发现就会回到刺激；激惹。'),
  ('968fd1f2-e8e1-5b61-84f3-d1a0e792fae5', 'The case stem named the hemoglobin before asking what to do next.', 'The exam-style stem first named the oxygen-carrying protein of red cells, then asked for the next step.', '病例题干先写出血红蛋白，再问下一步怎么做。'),
  ('4e71b93e-0931-5661-9707-c2f2d54a4bcb', 'The case note named the aplastic anemia before describing what happened next.', 'The note first named anemia from failed marrow blood-cell production, then said what followed.', '病历先写出再生障碍性贫血，再写接下来发生了什么。'),
  ('04e7230b-3db9-535b-812f-f9fc10d2619c', 'The admission note placed the pigment among the early working problems.', 'The first ward note included a colored substance in tissue or blood in the early problem list.', '入院记录把色素写进了初步问题。'),
  ('d0cb2570-1560-5f0c-9f5d-979043b26337', 'The classroom quiz asked students to recognise the pancytopenia from a short stem.', 'The quiz used a short stem and asked students to recognise low red cells, white cells, and platelets together.', '随堂测验用一小段题干，让学生认出全血细胞减少。'),
  ('12f164d2-388d-5a00-ac0e-bc0b4fc9d85e', 'In the anatomy lab a pin marked the heme on the demonstration specimen.', 'A lab pin showed where the iron-containing part of hemoglobin sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了血红素。'),
  ('38227adc-b09b-5502-b42c-18a4c059848f', 'The textbook treats the hemolytic anemia as core vocabulary, not extra trivia.', 'The book treats anemia from premature red-cell destruction as a must-know classroom term, not spare trivia.', '教材把溶血性贫血当作核心课堂词，而不是附加冷知识。'),
  ('d368550f-cea5-5775-aec9-3f31a62bb1f1', 'Her revision card grouped the electrolyte with two nearby classroom terms.', 'The revision card put an ion in body fluid such as sodium or potassium together with two neighboring class words.', '她的复习卡把电解质和两个邻近的课堂词放在一组。'),
  ('98d9194d-7c6a-5c99-834f-e242db85a69a', 'The handover sheet kept the clotting factors on its own line.', 'The handover kept plasma proteins of the coagulation cascade on a separate line.', '交接单给凝血因子单独留了一行。'),
  ('43f0bcae-0bdd-5401-8edf-dbb4e81202a0', 'The intern added spherocytosis to the problem list after morning teaching.', 'After the teaching round, the intern listed red cells that are sphere-shaped and fragile among the problems.', '晨间带教后，实习医生把球形红细胞增多写进了问题列表。'),
  ('56ea3e4a-8c85-5dfd-a0cc-48183251d200', 'On the ward round the registrar paused so juniors could name the nucleus.', 'During rounds the senior stopped and asked the juniors to name the cell compartment that holds most DNA.', '查房时，高年资住院医师停下来，让低年资医生说出细胞核。'),
  ('7b0fed6c-c0c5-5c70-89b8-fae39d1f2df8', 'The lecture slide highlighted the erythropoietin next to a simpler neighboring term.', 'The classroom slide put a kidney hormone that stimulates red-cell production beside a plainer nearby word.', '课堂幻灯把促红细胞生成素标在一个更浅的邻近词旁边。'),
  ('3c611e7b-2902-54d8-994c-ec0655d99eb1', 'The teaching lab slip called the result pernicious and left the numbers beside it.', 'The practice report labeled the result as destructive; in pernicious anemia, B12-deficiency anemia and kept the numbers next to it.', '教学化验单把结果写成恶性的，数字写在旁边。'),
  ('81e5be37-d94f-5290-aa77-542deb85f29d', 'The textbook figure labels the granulocytes beside the neighboring tissue.', 'The printed figure marks white cells with granules: neutrophils, eosinophils, basophils next to the nearby tissue.', '教材插图把粒细胞标在邻近组织旁边。'),
  ('6fb90b32-4bda-5599-bbad-b5af1db0f48f', 'In class the tutor pointed to the megaloblast on the wall chart.', 'The tutor used the wall chart and pointed to an abnormally large nucleated red-cell precursor.', '课堂上，老师指着墙上的图讲解巨幼红细胞。'),
  ('5de22b1f-b7e7-59f5-8950-9dd87e5346f3', 'In the skills lab students had to identify the eosinophil on a model.', 'Lab practice asked students to find a granulocyte involved in allergy and parasites on the model.', '技能实验室里，学生要在模型上认出嗜酸性粒细胞。'),
  ('3f0b5183-2854-58e7-8c9a-291c04fb7c7a', 'A margin gloss repeats the sickle cell anemia in smaller type beside the main paragraph.', 'The margin repeats an inherited anemia with sickle-shaped red cells in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出镰状细胞贫血。'),
  ('9e91c3ee-13c3-507c-a168-3e713f3c5e92', 'After history taking, the student wrote the basophil under current problems.', 'Once the history was finished, the student listed a granulocyte that releases histamine with the current problems.', '问完病史后，学生把嗜碱性粒细胞写在目前问题下面。'),
  ('d51944d9-8a70-5cbb-9940-352cd830ce2d', 'The attending asked whether this really was the neutrophil or a looser bedside word.', 'The consultant checked that the team meant the main phagocyte of acute bacterial infection, not a vaguer everyday word.', '主治医师追问：这里是不是中性粒细胞，还是只是更松的床旁说法。'),
  ('d650b90d-e7bf-5e14-b2cd-877197e2e6c4', 'A labelled classroom slide showed the arthralgias without extra commentary.', 'The teaching slide simply marked joint pains without necessary swelling and left the rest for discussion.', '一张带标注的课堂幻灯只标出关节痛，没有再加解释。'),
  ('25e4f213-805e-5199-9670-1b5b84cd9a5e', 'In the tutorial, each pair had to explain the agranulocyte in one spoken sentence.', 'Tutorial pairs had to say a white cell without obvious granules, such as a lymphocyte out loud in a single sentence.', '小组课上，每两人要用一句话口头解释无粒白细胞。'),
  ('7d65f428-de59-5d59-9eb7-ee6fe9044f69', 'At the teaching conference the film was used to locate the extremities.', 'The teaching meeting used the image so students could find the arms and legs.', '教学读片会上，用这张片子让学生找出四肢。'),
  ('68d63cc6-4e2f-5872-b19c-f778284e7b8d', 'Night handover listed the monocyte before the overnight plan.', 'The night team named a circulating precursor of macrophages first, then said what to do overnight.', '夜班交接时先提到单核细胞，再讲夜间计划。'),
  ('6e8d5c02-a762-59f9-92a0-8f51515637ce', 'The chapter margin lists the ulceration with other core classroom words.', 'The side note groups the process of forming an ulcer with the other must-know terms.', '章节页边把溃疡形成和其他课堂核心词列在一起。'),
  ('b0857941-eb45-5d03-92d4-e89d55c10551', 'Bedside teaching returned to the lymphocyte whenever the finding came up.', 'At the bedside the teacher kept coming back to the T or B white cell of adaptive immunity when that finding appeared.', '床旁带教时，一碰到这个发现就会回到淋巴细胞。'),
  ('2e242195-a40f-566f-869f-d793af6a4a04', 'The case stem named the thalassemia before asking what to do next.', 'The exam-style stem first named an inherited defect in globin-chain synthesis, then asked for the next step.', '病例题干先写出地中海贫血，再问下一步怎么做。'),
  ('6258e412-0d24-5136-b09e-e69a032b9325', 'The quiz asked which finding should be called polymorphonuclear.', 'The quiz wanted the finding that is honestly having a multi-lobed nucleus, as neutrophils do.', '测验问：哪个发现才该写成多形核的。'),
  ('b9288629-eea8-595c-94ff-86ef31bba48b', 'The admission note placed the thrombocytopenia among the early working problems.', 'The first ward note included an abnormally low platelet count in the early problem list.', '入院记录把血小板减少写进了初步问题。'),
  ('6733db33-26b4-5eb2-b65a-db0b5da1f30d', 'The tutor modelled how to detoxify in one calm spoken sentence.', 'The teacher showed how to to make a toxin less harmful in one quiet spoken line.', '老师示范：怎样用一句冷静的话来解毒。'),
  ('8d2249d7-1e94-567b-bbb0-9a41f2b948da', 'In the anatomy lab a pin marked the petechiae on the demonstration specimen.', 'A lab pin showed where tiny pinpoint hemorrhages in skin or mucosa sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了瘀点。'),
  ('728e512c-f700-579e-94d5-b2d5c932a3a7', 'The printed handover sheet kept the heparin on the first line.', 'The paper handover put an anticoagulant used to prevent clotting at the top of the list.', '打印的交接单把肝素放在第一行。'),
  ('806cef1c-cfe5-53e9-820b-def1bba017cc', 'Her revision card grouped the ecchymosis with two nearby classroom terms.', 'The revision card put a larger subcutaneous bleed; a bruise together with two neighboring class words.', '她的复习卡把瘀斑和两个邻近的课堂词放在一组。'),
  ('83532c44-e96d-50b4-869c-5dd28dcbf124', 'Pair work asked when a finding is phagocytic and when it is not.', 'Students had to say when a finding is able to engulf particles or microbes and when that word is too strong.', '结对练习要分清：什么时候算吞噬的，什么时候还不算。'),
  ('5c78e85d-3a92-5a06-b9cf-cb230ccb4ab7', 'The intern added purpura to the problem list after morning teaching.', 'After the teaching round, the intern listed purple skin spots from bleeding under the skin among the problems.', '晨间带教后，实习医生把紫癜写进了问题列表。'),
  ('5293f4ec-d523-5b29-bb13-665a54a0d41d', 'On the ward round the registrar paused so juniors could name the macrophages.', 'During rounds the senior stopped and asked the juniors to name tissue phagocytes derived from monocytes.', '查房时，高年资住院医师停下来，让低年资医生说出巨噬细胞。'),
  ('e69d9532-4088-558b-83c8-b2b1fa17fe37', 'The lecture slide highlighted the hemophilia next to a simpler neighboring term.', 'The classroom slide put an inherited clotting-factor deficiency with bleeding beside a plainer nearby word.', '课堂幻灯把血友病标在一个更浅的邻近词旁边。'),
  ('c9f68390-5cb7-5e8a-b5f4-5898771b3105', 'The case stem described an intramuscular change that students had to interpret.', 'The stem described a change that was into a muscle, a common injection route and asked students to read it.', '题干写到一个肌内的的改变，要学生自己判断。'),
  ('4c07b9d7-f594-59fc-9551-5514640d6cfb', 'The textbook figure labels the phagocytosis beside the neighboring tissue.', 'The printed figure marks engulfment of particles by a cell next to the nearby tissue.', '教材插图把吞噬作用标在邻近组织旁边。'),
  ('74cb642f-311e-58d8-9196-351a7e3b1101', 'The textbook treats the autoimmune disease as core vocabulary, not extra trivia.', 'The book treats disease in which the immune system attacks host tissue as a must-know classroom term, not spare trivia.', '教材把自身免疫病当作核心课堂词，而不是附加冷知识。'),
  ('c7d7ebb5-140f-5177-bf7c-96b9e765bcf9', 'In the skills lab students had to identify the megakaryocyte on a model.', 'Lab practice asked students to find the large marrow cell that sheds platelets on the model.', '技能实验室里，学生要在模型上认出巨核细胞。'),
  ('86a5f977-9adf-5e3a-9d5c-5b26d6426682', 'The progress note mentioned the hemostasis in one plain line.', 'The ward note used one simple line to record the stopping of bleeding.', '病程记录用一句平实的话写到了止血。'),
  ('032673a5-8037-592d-a40d-6ff5c5d71821', 'After history taking, the student wrote the hematuria under current problems.', 'Once the history was finished, the student listed blood in the urine with the current problems.', '问完病史后，学生把血尿写在目前问题下面。'),
  ('fce5e45c-b7f3-5d65-8114-5aac48304e4e', 'The attending asked whether this really was the hemarthrosis or a looser bedside word.', 'The consultant checked that the team meant bleeding into a joint, not a vaguer everyday word.', '主治医师追问：这里是不是关节积血，还是只是更松的床旁说法。'),
  ('28174567-eac1-5b80-b7d9-600b65877ef1', 'A labelled classroom slide showed the myeloblast without extra commentary.', 'The teaching slide simply marked an immature myeloid white-cell precursor and left the rest for discussion.', '一张带标注的课堂幻灯只标出成髓细胞，没有再加解释。'),
  ('36be2590-2e42-5dc0-9416-2a67628c2ad5', 'In the tutorial, each pair had to explain the leukemia in one spoken sentence.', 'Tutorial pairs had to say a malignancy of white blood cells out loud in a single sentence.', '小组课上，每两人要用一句话口头解释白血病。'),
  ('266d144f-4af8-5874-904d-edc6d03297ef', 'At the teaching conference the film was used to locate the neoplasms.', 'The teaching meeting used the image so students could find abnormal new growths; tumors.', '教学读片会上，用这张片子让学生找出肿瘤；新生物。'),
  ('c6b0a633-93cf-536b-9b09-70e0d3df8fe5', 'Night handover listed the lymphoblast before the overnight plan.', 'The night team named an immature lymphocyte precursor first, then said what to do overnight.', '夜班交接时先提到成淋巴细胞，再讲夜间计划。'),
  ('06f709b0-2434-5f67-a124-5315f4ff762e', 'At the bedside the tutor asked a junior to show the acute myelogenous leukemia on the patient diagram.', 'By the bed the tutor asked a junior to show a fast myeloid-line blood cancer on the patient diagram.', '床旁，老师让低年资医生在患者示意图上指出急性髓系白血病。'),
  ('71941e70-67f7-5a0f-a6f7-84165068f2ea', 'Bedside teaching returned to the hypercalcemia whenever the finding came up.', 'At the bedside the teacher kept coming back to an abnormally high blood calcium when that finding appeared.', '床旁带教时，一碰到这个发现就会回到高钙血症。'),
  ('d0a9f260-702f-52e8-a992-356162ab121e', 'The case stem named the itching before asking what to do next.', 'The exam-style stem first named the sensation that makes a person want to scratch, then asked for the next step.', '病例题干先写出瘙痒，再问下一步怎么做。'),
  ('1247d5d4-0a64-5f67-a816-17c1b87c0402', 'The case note named the acute lymphocytic leukemia before describing what happened next.', 'The note first named a fast lymphoid-line blood cancer, especially in children, then said what followed.', '病历先写出急性淋巴细胞白血病，再写接下来发生了什么。'),
  ('0cf70485-96aa-5a62-a99a-ca585d1c512d', 'The admission note placed the rash among the early working problems.', 'The first ward note included a visible eruption on the skin in the early problem list.', '入院记录把皮疹写进了初步问题。'),
  ('7a45fa84-cdc4-5364-bdc5-f65c96179b82', 'The classroom quiz asked students to recognise the sneezing from a short stem.', 'The quiz used a short stem and asked students to recognise a sudden explosive expulsion of air from the nose.', '随堂测验用一小段题干，让学生认出喷嚏。'),
  ('0c16a8c9-345a-59ab-aac4-95e11caf4b23', 'On rounds the registrar asked for the everyday function of the chronic myelogenous leukemia.', 'On rounds the senior asked what a slower myeloid leukemia often with a Philadelphia chromosome does in ordinary words.', '查房时，住院医师问慢性髓系白血病日常起什么作用。'),
  ('552c1f3f-9147-56a0-8a01-00b60b8e4296', 'The printed handover sheet kept the urticaria on the first line.', 'The paper handover put itchy wheals; hives at the top of the list.', '打印的交接单把荨麻疹放在第一行。'),
  ('5417db13-1d14-553c-96c7-853995fef167', 'Her revision card grouped the immunodeficiency with two nearby classroom terms.', 'The revision card put impaired ability to fight infection together with two neighboring class words.', '她的复习卡把免疫缺陷和两个邻近的课堂词放在一组。'),
  ('0919b941-a8bc-54d0-8cc2-456878ce93ff', 'The consultant summary named the dysgammaglobulinemia and then restated it in plain words.', 'The senior first said abnormal immunoglobulin levels, then repeated the idea in everyday language.', '顾问医师先点出丙种球蛋白异常血症，再用白话复述一遍。'),
  ('1843fcc0-d4be-5f3b-a3f9-7d6390329f3f', 'In the lab a pin and a tag marked the multiple myeloma on the model.', 'A lab pin and tag showed a plasma-cell cancer of bone marrow on the model.', '实验室里，模型和标签标出了多发性骨髓瘤。'),
  ('2b4ec80b-b75b-58a1-8884-743b6adc79f9', 'The tutorial pair had to point to the plasma cells and say it aloud.', 'Each pair pointed to antibody-secreting B-lineage cells and said the words out loud.', '小组课上，两人要指出浆细胞并大声读出来。'),
  ('18de23cd-e2e9-577f-a627-5429da58d6a5', 'On the board the tutor underlined extrinsic as the tighter classroom choice.', 'The teacher marked this word, meaning coming from outside the organ or pathway, as the stricter classroom choice.', '老师在黑板上划出外源性的，作为更严的课堂用词。'),
  ('8c0ba720-ecda-54ab-8d33-05339a8b7264', 'The teaching lab slip called the result osteolytic and left the numbers beside it.', 'The practice report labeled the result as causing bone destruction and kept the numbers next to it.', '教学化验单把结果写成溶骨的，数字写在旁边。'),
  ('8a53abbd-4efa-5b24-b1f2-84959024ef1d', 'During rounds the intern defended calling the course intrinsic.', 'On rounds the intern explained why the course counted as arising from within the organ or pathway.', '查房时，实习医生说明为什么病程可以写成内源性的。'),
  ('c4b0d391-60cf-5075-81c1-26099d247b3f', 'In class the tutor pointed to the lymphadenopathy on the wall chart.', 'The tutor used the wall chart and pointed to enlarged or abnormal lymph nodes.', '课堂上，老师指着墙上的图讲解淋巴结病。'),
  ('3eab340c-0513-5a5d-a8fc-f76dd11dc77d', 'In the skills lab students had to identify the zygote on a model.', 'Lab practice asked students to find the cell formed by fusion of sperm and ovum on the model.', '技能实验室里，学生要在模型上认出受精卵。'),
  ('0986b879-13bf-5e5d-b465-bbfa58208c95', 'The progress note mentioned the quadruplet in one plain line.', 'The ward note used one simple line to record one of four siblings from the same pregnancy.', '病程记录用一句平实的话写到了四胞胎之一。'),
  ('189ac29f-2fc9-5765-ad02-1998c4211963', 'After history taking, the student wrote the oviduct under current problems.', 'Once the history was finished, the student listed the tube that carries the ovum; fallopian tube with the current problems.', '问完病史后，学生把输卵管写在目前问题下面。'),
  ('8568f0a0-3a45-55e5-8793-cbf11677b2fa', 'The tutor asked for dissimilar rather than a looser bedside word.', 'The teacher wanted this exact word, meaning not alike, not a vaguer bedside term.', '老师要求用这个词（不相同的），不要换成更松的床旁说法。'),
  ('dbfc6846-06b6-5c71-9905-77e4857bdcb2', 'A labelled classroom slide showed the endometrium without extra commentary.', 'The teaching slide simply marked the inner lining of the uterus and left the rest for discussion.', '一张带标注的课堂幻灯只标出子宫内膜，没有再加解释。'),
  ('56023838-9b9c-5c53-a1a7-37fc01043c08', 'Pair work practised how to abort without copying the textbook line.', 'Students practised how to to end a pregnancy before viability in their own words.', '结对练习：用自己的话流产；中止妊娠，不要照抄教材原句。'),
  ('83f66066-2fe9-5da6-819d-88c7b84aee84', 'At the teaching conference the film was used to locate the embryo.', 'The teaching meeting used the image so students could find the early developing offspring before the fetal stage.', '教学读片会上，用这张片子让学生找出胚胎。'),
  ('08f944cf-6f0b-5546-887a-9ae25a68f680', 'Night handover listed the vagina before the overnight plan.', 'The night team named the canal from the uterus to the outside first, then said what to do overnight.', '夜班交接时先提到阴道，再讲夜间计划。'),
  ('bf3e7175-7735-5eb7-925c-edcad1a9043f', 'The wall chart boxed the chorionic sac so students could find it quickly.', 'The wall chart put a box around the early extra-embryonic sac formed by chorion to make it easy to spot.', '墙上的图给绒毛膜囊加了框，方便学生快速找到。'),
  ('d6937476-fd27-5fbd-8207-ec3af3708027', 'Bedside teaching returned to the cervix whenever the finding came up.', 'At the bedside the teacher kept coming back to the lower neck of the uterus when that finding appeared.', '床旁带教时，一碰到这个发现就会回到宫颈。'),
  ('b077deff-6d61-5c0c-97e2-7110b438f38d', 'The case stem named the chorion before asking what to do next.', 'The exam-style stem first named the outer fetal membrane that contributes to the placenta, then asked for the next step.', '病例题干先写出绒毛膜，再问下一步怎么做。'),
  ('2145143c-3ece-577d-892f-1b803ed474d1', 'The tutorial pair had to point to the fallopian tubes and say it aloud.', 'Each pair pointed to the tubes from ovary to uterus and said the words out loud.', '小组课上，两人要指出输卵管并大声读出来。'),
  ('c21eff4b-90fd-5d9c-841f-9e50645edd49', 'The admission note placed the gonadotropin among the early working problems.', 'The first ward note included a hormone that stimulates the gonads in the early problem list.', '入院记录把促性腺激素写进了初步问题。'),
  ('ab4d1fd0-76ad-56e7-9566-1993e458f238', 'The classroom quiz asked students to recognise the fertilization from a short stem.', 'The quiz used a short stem and asked students to recognise union of sperm and ovum.', '随堂测验用一小段题干，让学生认出受精。'),
  ('fa7fd369-4dc8-573e-8eef-848c91e4c9f3', 'The teaching conference used one slide only for the corpus luteum.', 'The conference reserved a whole slide for the post-ovulatory follicle that secretes progesterone.', '教学讨论会单独用一张幻灯讲黄体。'),
  ('8689468b-43cb-561d-8ab2-cb42f40726b0', 'Her revision list put the pregnancy tests with two neighboring system terms.', 'The revision list grouped tests that detect hCG to confirm pregnancy with two nearby system terms.', '她的复习表把妊娠试验和两个邻近系统词放在一起。'),
  ('f7e4f66a-60a9-52ad-83e6-ac9e34a47298', 'Her revision card grouped the placenta with two nearby classroom terms.', 'The revision card put the organ of exchange between mother and fetus together with two neighboring class words.', '她的复习卡把胎盘和两个邻近的课堂词放在一组。'),
  ('2f551338-1a05-5ebc-86a1-07a3ec84a508', 'The consultant summary named the fetus and then restated it in plain words.', 'The senior first said the unborn offspring after the embryonic period, then repeated the idea in everyday language.', '顾问医师先点出胎儿，再用白话复述一遍。'),
  ('55654552-a481-59b2-922e-be9246b5ab6d', 'The lecture placed the amniotic sac next to related classroom structures.', 'The lecture sat the fluid-filled sac around the fetus beside related classroom structures.', '讲课把羊膜囊放在相关课堂结构旁边。'),
  ('b39e4017-39d1-5fd4-8e2f-e868599ebec3', 'The case note named the umbilical cord before describing what happened next.', 'The note first named the cord linking fetus and placenta, then said what followed.', '病历先写出脐带，再写接下来发生了什么。'),
  ('bba0be52-34d4-5f22-bf76-d5521817b067', 'The lecture slide highlighted the amniorrhea next to a simpler neighboring term.', 'The classroom slide put leakage of amniotic fluid beside a plainer nearby word.', '课堂幻灯把羊水流出标在一个更浅的邻近词旁边。'),
  ('dc55edca-9068-5f1e-82f1-4cf133437886', 'A one-paragraph case opened by naming the amnion before later findings.', 'The short case first named the inner fetal membrane around the amniotic fluid, then listed what came next.', '短病例开头先写出羊膜，再写后面的发现。'),
  ('72fef5fa-1d61-5c0d-8877-8151ec259cb4', 'The textbook figure labels the trimester beside the neighboring tissue.', 'The printed figure marks one of the three three-month spans of pregnancy next to the nearby tissue.', '教材插图把孕期（三个月）标在邻近组织旁边。'),
  ('8246c897-a3c9-51cb-a2d9-c970d64f5e53', 'Her presentation stayed menstrual from admission through the first night.', 'From admission to the first night, the picture remained relating to menstruation.', '从入院到第一夜，她的表现一直是月经的。'),
  ('5ba1c884-6ffb-58b1-a96b-4d7abb500211', 'In the skills lab students had to identify the parturition on a model.', 'Lab practice asked students to find the process of giving birth on the model.', '技能实验室里，学生要在模型上认出分娩。'),
  ('93d4ca2d-235a-5a75-948a-8185a1d2ec03', 'The handover sheet kept the birth canal on its own line.', 'The handover kept the passage the fetus travels during birth on a separate line.', '交接单给产道单独留了一行。'),
  ('b626e9e8-c70b-5446-93ba-640a88eb8941', 'After history taking, the student wrote the dystocia under current problems.', 'Once the history was finished, the student listed difficult labor with the current problems.', '问完病史后，学生把难产写在目前问题下面。'),
  ('6679fd21-b364-51f0-9f70-6ac5c831a35b', 'The attending asked whether this really was the gravida or a looser bedside word.', 'The consultant checked that the team meant a woman who is or has been pregnant, not a vaguer everyday word.', '主治医师追问：这里是不是孕妇，还是只是更松的床旁说法。'),
  ('93034e78-f0f2-5832-ba56-d355325aa019', 'A short teaching note introduced the cesarean birth before any later complications.', 'The teaching note named delivery of the fetus through an abdominal incision first, before later complications.', '短教学笔记先介绍剖宫产，再谈后续并发症。'),
  ('e1e25d20-5304-5dac-bfb7-8e2622ec68a0', 'In the tutorial, each pair had to explain the primigravida in one spoken sentence.', 'Tutorial pairs had to say a woman pregnant for the first time out loud in a single sentence.', '小组课上，每两人要用一句话口头解释初孕妇。'),
  ('885fc5c5-bf21-5862-bbb4-a23fda71de70', 'At the teaching conference the film was used to locate the oxytocin.', 'The teaching meeting used the image so students could find a hormone that contracts the uterus and ejects milk.', '教学读片会上，用这张片子让学生找出缩宫素。'),
  ('935a7da3-150e-5e62-8601-9fded9f0f1e8', 'Night handover listed the para before the overnight plan.', 'The night team named the number of pregnancies that reached viability first, then said what to do overnight.', '夜班交接时先提到产次，再讲夜间计划。'),
  ('17281108-f2dd-542c-a788-5fd07a4472ce', 'The chapter margin lists the prostaglandin with other core classroom words.', 'The side note groups a lipid mediator that can ripen the cervix and cause contraction with the other must-know terms.', '章节页边把前列腺素和其他课堂核心词列在一起。'),
  ('b70085c7-7144-592e-8a2a-9f0739f2cb47', 'Pair work asked when a finding is inheritable and when it is not.', 'Students had to say when a finding is able to be passed from parent to offspring and when that word is too strong.', '结对练习要分清：什么时候算可遗传的，什么时候还不算。'),
  ('5c4e2a20-fadd-5063-984a-42bca99cd763', 'The case stem named the meiosis before asking what to do next.', 'The exam-style stem first named germ-cell division that yields haploid gametes, then asked for the next step.', '病例题干先写出减数分裂，再问下一步怎么做。'),
  ('257cd399-834d-53f5-9f6d-eec10e163729', 'The tutor wrote the offspring on the board and circled the classroom sense.', 'On the board the tutor wrote children or descendants and marked the classroom meaning.', '老师把子代写在黑板上，并圈出课堂义。'),
  ('ff48c527-6323-5c1c-9742-e71e8a9bf093', 'The admission note placed the mitosis among the early working problems.', 'The first ward note included cell division that yields two identical diploid cells in the early problem list.', '入院记录把有丝分裂写进了初步问题。'),
  ('e3cb3ef8-35f4-5f28-a59b-4ff6664c8367', 'The case stem described a dominant change that students had to interpret.', 'The stem described a change that was expressed even when only one allele is present and asked students to read it.', '题干写到一个显性的的改变，要学生自己判断。'),
  ('18868548-7024-54bd-981c-33731feb88a6', 'In the anatomy lab a pin marked the triplet on the demonstration specimen.', 'A lab pin showed where one of three siblings from the same pregnancy sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了三胞胎之一。'),
  ('05051aa0-ee44-543d-923d-6990d450d9fa', 'Her presentation stayed recessive from admission through the first night.', 'From admission to the first night, the picture remained expressed only when both alleles are the variant.', '从入院到第一夜，她的表现一直是隐性的。'),
  ('8501c572-f2c4-5f7c-af23-db84cef72209', 'The wall chart boxed the cell division so students could find it quickly.', 'The wall chart put a box around the process of one cell becoming two to make it easy to spot.', '墙上的图给细胞分裂加了框，方便学生快速找到。'),
  ('1099e39f-759c-56cd-bae7-5aaa2e77b082', 'The consultant summary named the rearrangement and then restated it in plain words.', 'The senior first said a structural change in chromosome order, then repeated the idea in everyday language.', '顾问医师先点出重排，再用白话复述一遍。'),
  ('5a86e9c5-d5de-5975-86ad-1d6832c930e2', 'Handover kept the wording identical so the night team would not soften it.', 'The outgoing team kept the precise word that means the same, as in identical twins from one zygote.', '交接时坚持用同卵的；相同的这个写法，避免夜班说得太软。'),
  ('5ce91113-da0a-5b6b-bb94-c6d03537a161', 'On the ward round the registrar paused so juniors could name the fragment.', 'During rounds the senior stopped and asked the juniors to name a broken piece of a chromosome or molecule.', '查房时，高年资住院医师停下来，让低年资医生说出片段。'),
  ('e0b9ccd6-bb8a-585c-ad40-b72fe285e9b2', 'The lecture slide highlighted the preeclampsia next to a simpler neighboring term.', 'The classroom slide put pregnancy hypertension with organ injury, often proteinuria beside a plainer nearby word.', '课堂幻灯把子痫前期标在一个更浅的邻近词旁边。'),
  ('d2702193-1e24-5dac-bffb-4b8601240f28', 'The matching quiz asked students to pair the cleft palate with its classroom gloss.', 'The matching quiz linked a congenital gap in the palate to its classroom gloss.', '配对测验要求把腭裂和课堂释义对上。'),
  ('734d50ac-fc0a-5997-9d07-30ca4cfa917b', 'The teaching conference used one slide only for the diabetes mellitus.', 'The conference reserved a whole slide for a disorder of high blood glucose from insulin lack or resistance.', '教学讨论会单独用一张幻灯讲糖尿病。'),
  ('b6540e80-68c6-55f8-987c-c1b1c1ce4d25', 'In class the tutor pointed to the toxemia on the wall chart.', 'The tutor used the wall chart and pointed to an older name for preeclampsia-related pregnancy toxicity.', '课堂上，老师指着墙上的图讲解毒血症。'),
  ('4eb906e6-0099-5584-a922-2a9e7c6f393b', 'In the skills lab students had to identify the amniocentesis on a model.', 'Lab practice asked students to find sampling amniotic fluid, usually for fetal testing on the model.', '技能实验室里，学生要在模型上认出羊膜穿刺。'),
  ('388844cf-8a8b-584b-b2c4-5fa09937be3c', 'The progress note mentioned the proteinuria in one plain line.', 'The ward note used one simple line to record protein in the urine.', '病程记录用一句平实的话写到了蛋白尿。'),
  ('a3a25a64-5879-5b3e-a0a9-ca9783dc8bb1', 'The note used ectopic to mark the quality of the finding.', 'The chart chose this adjective to say the finding was located outside the normal site, as in ectopic pregnancy.', '病历用这个词标明该发现是异位的。'),
  ('26e8d82b-067c-57b8-85c5-5edc80b137f3', 'The attending asked whether this really was the karyotype or a looser bedside word.', 'The consultant checked that the team meant the chromosome set of a cell arranged for study, not a vaguer everyday word.', '主治医师追问：这里是不是核型，还是只是更松的床旁说法。'),
  ('7ec45787-32f6-506b-a9eb-c66f6d91dff7', 'A labelled classroom slide showed the salpingitis without extra commentary.', 'The teaching slide simply marked inflammation of a fallopian tube and left the rest for discussion.', '一张带标注的课堂幻灯只标出输卵管炎，没有再加解释。'),
  ('670d368e-c1e5-5b4f-a2d1-c7ee9b46fa92', 'The first chapter figure was a simple diagram of the chorionic villus.', 'The opening figure was a plain diagram of a placental projection used in some prenatal tests.', '该章第一张图就是绒毛的简单示意图。'),
  ('d118b2c1-f43f-5f01-af45-2408aca1f2a9', 'At the teaching conference the film was used to locate the endometriosis.', 'The teaching meeting used the image so students could find endometrial-like tissue growing outside the uterus.', '教学读片会上，用这张片子让学生找出子宫内膜异位症。'),
  ('fbf92df8-2488-5c85-9140-0b1a7a532a72', 'In the skills lab, students practiced how to transmit this finding safely.', 'Lab practice was about how to to pass a trait or infection from one individual to another without rushing.', '技能课上，学生练习如何稳妥地传播；传递这一发现。'),
  ('7dc2493d-a392-5223-ab1d-3b406afa05f4', 'The wall chart boxed the mendelian fashion so students could find it quickly.', 'The wall chart put a box around inheritance following Mendel''s single-gene rules to make it easy to spot.', '墙上的图给孟德尔方式加了框，方便学生快速找到。'),
  ('8018a3f2-bce1-5a4c-a80a-31dd12243a77', 'Students compared a laparoscopic pattern with the opposite classroom example.', 'The class set a done through a laparoscope pattern against the opposite teaching example.', '学生把腹腔镜的的模式和课堂上相反的例子对照。'),
  ('f2e157c4-a0a3-5b79-ac18-05743fcefa38', 'The case stem named the miscarriage before asking what to do next.', 'The exam-style stem first named spontaneous loss of a pregnancy before viability, then asked for the next step.', '病例题干先写出自然流产，再问下一步怎么做。'),
  ('9df3db6e-2bf3-52fa-adc9-c95ad1d5773f', 'The tutor wrote the immunogenetics on the board and circled the classroom sense.', 'On the board the tutor wrote the genetics of immune-system variation and marked the classroom meaning.', '老师把免疫遗传学写在黑板上，并圈出课堂义。'),
  ('a6d3921d-143d-5782-8a9b-211df75f3856', 'The admission note placed the incompetence among the early working problems.', 'The first ward note included failure of a valve or cervix to close properly in the early problem list.', '入院记录把关闭不全；功能不全写进了初步问题。'),
  ('0cb75bd3-2c1d-5b8e-99d2-790627270966', 'The matching quiz asked students to pair the induced abortion with its classroom gloss.', 'The matching quiz linked intentional ending of a pregnancy to its classroom gloss.', '配对测验要求把人工流产和课堂释义对上。'),
  ('9e51439a-1bce-567e-95a6-bf6d8eac42ba', 'The quiz stem asked what the intern should incur next.', 'The quiz asked for the next action: to to bring a risk or complication upon oneself.', '测验题干问实习医生下一步该招致什么。'),
  ('3c0c073b-e409-5134-afa7-133c6e7355b6', 'The printed handover sheet kept the suction on the first line.', 'The paper handover put removal of fluid or tissue by vacuum at the top of the list.', '打印的交接单把吸引放在第一行。'),
  ('e8cca73c-9dcc-54ce-bc5f-b3aed1d97efe', 'Her revision card grouped the mutagen with two nearby classroom terms.', 'The revision card put an agent that causes mutation together with two neighboring class words.', '她的复习卡把诱变剂和两个邻近的课堂词放在一组。'),
  ('41a7afdb-d942-5561-9aed-aadd79d950d8', 'A margin gloss repeats the birth defect in smaller type beside the main paragraph.', 'The margin repeats a structural or functional abnormality present at birth in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出出生缺陷。'),
  ('577382b1-e827-5294-baec-378bec547d03', 'The note used mutagenic to mark the quality of the finding.', 'The chart chose this adjective to say the finding was able to cause mutation.', '病历用这个词标明该发现是诱变的。'),
  ('40c0da17-1b8e-59bf-ae6f-3f4e4db798c3', 'On the ward round the registrar paused so juniors could name the teratogen.', 'During rounds the senior stopped and asked the juniors to name an agent that causes fetal malformation.', '查房时，高年资住院医师停下来，让低年资医生说出致畸物。'),
  ('5865c415-6d7e-503d-94d7-549d954a6416', 'The lecture slide highlighted the carcinogen next to a simpler neighboring term.', 'The classroom slide put an agent that can cause cancer beside a plainer nearby word.', '课堂幻灯把致癌物标在一个更浅的邻近词旁边。'),
  ('0b881f49-8407-5f86-ab1c-139432775a86', 'A one-paragraph case opened by naming the malformation before later findings.', 'The short case first named an abnormal anatomic shape present from development, then listed what came next.', '短病例开头先写出畸形，再写后面的发现。'),
  ('7b3e39ce-be26-5ca9-9c6e-28f62b6b3102', 'The textbook figure labels the albinism beside the neighboring tissue.', 'The printed figure marks a genetic lack of normal pigment next to the nearby tissue.', '教材插图把白化病标在邻近组织旁边。'),
  ('4debb008-d321-5eea-87f9-1d7e46070255', 'In class the tutor pointed to the rubella on the wall chart.', 'The tutor used the wall chart and pointed to German measles, a viral rash illness dangerous in early pregnancy.', '课堂上，老师指着墙上的图讲解风疹。'),
  ('ef143244-1065-56e1-8f95-79878827bf56', 'In the skills lab students had to identify the pigmentation on a model.', 'Lab practice asked students to find the coloring of skin or other tissue on the model.', '技能实验室里，学生要在模型上认出色素沉着。'),
  ('881d96e9-3cf6-533e-8fc3-555a91efec6b', 'The progress note mentioned the homozygote in one plain line.', 'The ward note used one simple line to record an individual with two identical alleles of a gene.', '病程记录用一句平实的话写到了纯合子。'),
  ('8b2008d8-fedd-52c2-bbbc-3fb77785b928', 'After history taking, the student wrote the measles under current problems.', 'Once the history was finished, the student listed a highly contagious viral rash illness with the current problems.', '问完病史后，学生把麻疹写在目前问题下面。'),
  ('082a60ae-c244-5365-a71c-be1090fb8387', 'The attending asked whether this really was the progeny or a looser bedside word.', 'The consultant checked that the team meant offspring, not a vaguer everyday word.', '主治医师追问：这里是不是后代，还是只是更松的床旁说法。'),
  ('09dd431a-a492-52ea-9da7-c02ac53f124f', 'A short teaching note introduced the herpes simplex before any later complications.', 'The teaching note named a viral infection causing vesicular sores first, before later complications.', '短教学笔记先介绍单纯疱疹，再谈后续并发症。'),
  ('98ff8748-01a8-5db0-bee7-f8a73762657b', 'In the tutorial, each pair had to explain the schizophrenia in one spoken sentence.', 'Tutorial pairs had to say a severe psychiatric disorder of thought and perception out loud in a single sentence.', '小组课上，每两人要用一句话口头解释精神分裂症。'),
  ('21887fd2-7dfe-5db4-ad40-ea32c8649f8a', 'At the teaching conference the film was used to locate the syphilis.', 'The teaching meeting used the image so students could find a sexually transmitted spirochetal infection.', '教学读片会上，用这张片子让学生找出梅毒。'),
  ('2bf22afa-7c23-5ee3-a387-74bf467fb2ec', 'Night handover listed the counselor before the overnight plan.', 'The night team named a person who gives genetic or clinical advice first, then said what to do overnight.', '夜班交接时先提到咨询者，再讲夜间计划。'),
  ('8ca7f9c0-3a61-56ca-b6dd-c2250ee5ad98', 'The chapter margin lists the atresia with other core classroom words.', 'The side note groups congenital absence or closure of an opening with the other must-know terms.', '章节页边把闭锁和其他课堂核心词列在一起。'),
  ('71e32ab5-2375-5d87-a7e6-921f0b412ee0', 'Bedside teaching returned to the mutant whenever the finding came up.', 'At the bedside the teacher kept coming back to an organism or gene carrying a mutation when that finding appeared.', '床旁带教时，一碰到这个发现就会回到突变体。'),
  ('4d001451-7c24-5a80-84d1-fd6eacbe8849', 'The case stem named the anencephalus before asking what to do next.', 'The exam-style stem first named a fetus lacking major parts of the brain and skull, then asked for the next step.', '病例题干先写出无脑畸形，再问下一步怎么做。'),
  ('a308ee8e-9774-59f7-8c31-17d8871c08eb', 'The tutor asked for prenatal rather than a looser bedside word.', 'The teacher wanted this exact word, meaning before birth, not a vaguer bedside term.', '老师要求用这个词（产前的），不要换成更松的床旁说法。'),
  ('f4067fa5-4fe8-57d5-8dce-e194dd0a364e', 'Students had to explain the spina bifida in one plain sentence of their own.', 'Each student had to say a neural-tube defect with incomplete vertebral closure in one ordinary sentence.', '学生要用自己的一句白话解释脊柱裂。'),
  ('ef71741f-e190-5038-9847-73fc534af431', 'The case stem described a lethal change that students had to interpret.', 'The stem described a change that was able to cause death and asked students to read it.', '题干写到一个致死的的改变，要学生自己判断。'),
  ('63eb9375-2caf-59fd-8098-e4c295690f12', 'On rounds the registrar asked for the everyday function of the cleft lip.', 'On rounds the senior asked what a congenital gap in the upper lip does in ordinary words.', '查房时，住院医师问唇裂日常起什么作用。'),
  ('37ae9f28-12c6-5d34-9618-bad5d2a11f6c', 'The printed handover sheet kept the euphenics on the first line.', 'The paper handover put improving the expressed phenotype without changing the genotype at the top of the list.', '打印的交接单把表型矫正放在第一行。'),
  ('cc6ac4ad-9b32-56e0-b186-7ae203228dde', 'The attending asked whether the process was truly euphenic in this patient.', 'The consultant checked that the process really was relating to treatment that improves phenotype here.', '主治医师问：这个过程在该患者身上是否真的是表型矫正的。'),
  ('7923d05e-391d-52da-b9b5-79f722f0cf78', 'Students compared an endocrine pattern with the opposite classroom example.', 'The class set a relating to hormone-secreting glands pattern against the opposite teaching example.', '学生把内分泌的的模式和课堂上相反的例子对照。'),
  ('8771bb61-558d-5367-8e04-fd785fd304c6', 'The intern added reproduction to the problem list after morning teaching.', 'After the teaching round, the intern listed the process of producing offspring among the problems.', '晨间带教后，实习医生把生殖写进了问题列表。'),
  ('adafa249-2626-59f0-934c-fada03941b63', 'On the ward round the registrar paused so juniors could name the dwarf.', 'During rounds the senior stopped and asked the juniors to name a person with marked short stature.', '查房时，高年资住院医师停下来，让低年资医生说出侏儒。'),
  ('1a721564-0d1d-5d47-9578-b81c6576af26', 'The lecture slide highlighted the metabolism next to a simpler neighboring term.', 'The classroom slide put the sum of chemical reactions in the body beside a plainer nearby word.', '课堂幻灯把代谢标在一个更浅的邻近词旁边。'),
  ('51c4693e-7bf3-560a-a3d9-787c3a67e2cb', 'A one-paragraph case opened by naming the nutrien before later findings.', 'The short case first named a classroom spelling of nutrient, a food substance the body uses, then listed what came next.', '短病例开头先写出营养素，再写后面的发现。'),
  ('4158fd84-f33b-54c0-aa44-1f0949392a57', 'The teaching conference used one slide only for the target tissue.', 'The conference reserved a whole slide for the tissue on which a hormone acts.', '教学讨论会单独用一张幻灯讲靶组织。'),
  ('e36fb0e6-86d8-5198-8c4a-6e8bfa934253', 'In class the tutor pointed to the gland on the wall chart.', 'The tutor used the wall chart and pointed to an organ or cell group that secretes a product.', '课堂上，老师指着墙上的图讲解腺。'),
  ('9bbeebfc-cee0-563f-bfb4-b6b95aa72309', 'In the skills lab students had to identify the receptor on a model.', 'Lab practice asked students to find a protein that binds a ligand and starts a signal on the model.', '技能实验室里，学生要在模型上认出受体。'),
  ('9c8ab71d-28dd-55ce-85e4-062e32538ed3', 'Pair work asked when a finding is glandular and when it is not.', 'Students had to say when a finding is relating to a gland and when that word is too strong.', '结对练习要分清：什么时候算腺的，什么时候还不算。'),
  ('e1cfb5c6-230d-5075-ac1c-2e2c4369adc4', 'The note used hormonal to mark the quality of the finding.', 'The chart chose this adjective to say the finding was relating to hormones.', '病历用这个词标明该发现是激素的。'),
  ('1ad65ad0-e039-521b-a007-0a2ded747f44', 'The attending asked whether this really was the steroid or a looser bedside word.', 'The consultant checked that the team meant a corticosteroid or related antiinflammatory hormone analog, not a vaguer everyday word.', '主治医师追问：这里是不是类固醇，还是只是更松的床旁说法。'),
  ('76a5b28b-7c0a-5963-89de-dbb016f8dd26', 'A labelled classroom slide showed the epinephrine without extra commentary.', 'The teaching slide simply marked the American pharmacologic name for adrenaline and left the rest for discussion.', '一张带标注的课堂幻灯只标出肾上腺素，没有再加解释。'),
  ('f8d7121d-d0bc-5b35-9bbd-5e33f36ab58b', 'In the tutorial, each pair had to explain the lipid in one spoken sentence.', 'Tutorial pairs had to say a fat-soluble molecule such as triglyceride or cholesterol out loud in a single sentence.', '小组课上，每两人要用一句话口头解释脂质。'),
  ('13372b69-ec16-5d67-86c5-0cab7ed08dd7', 'At the teaching conference the film was used to locate the norepinephrine.', 'The teaching meeting used the image so students could find a catecholamine neurotransmitter and vasopressor.', '教学读片会上，用这张片子让学生找出去甲肾上腺素。'),
  ('70fdaf12-42d5-506c-a3fb-c1bbbaa67144', 'Night handover listed the protein before the overnight plan.', 'The night team named a polymer of amino acids with structural or enzyme roles first, then said what to do overnight.', '夜班交接时先提到蛋白质，再讲夜间计划。'),
  ('12829e1e-f6af-59f8-b073-15f03725bf80', 'The wall chart boxed the proteinlike compound so students could find it quickly.', 'The wall chart put a box around a peptide or protein-like messenger to make it easy to spot.', '墙上的图给蛋白质样化合物加了框，方便学生快速找到。'),
  ('320ef2b6-8395-5ebb-879f-2bdbb0b76bdf', 'Bedside teaching returned to the gonad whenever the finding came up.', 'At the bedside the teacher kept coming back to an ovary or testis when that finding appeared.', '床旁带教时，一碰到这个发现就会回到性腺。'),
  ('f803f477-67be-55f9-9b4f-be042d3d617c', 'Handover kept the wording exocrine so the night team would not soften it.', 'The outgoing team kept the precise word that means secreting through a duct to a surface.', '交接时坚持用外分泌的这个写法，避免夜班说得太软。'),
  ('98f1b6e7-fcdb-5d9b-96ac-843c3aee764f', 'The tutor wrote the cortex on the board and circled the classroom sense.', 'On the board the tutor wrote the outer layer of an organ such as kidney or adrenal and marked the classroom meaning.', '老师把皮质写在黑板上，并圈出课堂义。'),
  ('01076c34-3151-5098-8947-9e0ace5b706d', 'A short teaching note introduced the islets of langerhans before any later complications.', 'The teaching note named the endocrine cell clusters of the pancreas first, before later complications.', '短教学笔记先介绍胰岛，再谈后续并发症。'),
  ('80fc3d79-410c-514b-8872-af756bb6c2d9', 'The teaching lab slip called the result ovarian and left the numbers beside it.', 'The practice report labeled the result as relating to the ovary and kept the numbers next to it.', '教学化验单把结果写成卵巢的，数字写在旁边。'),
  ('eb1c0b04-a1e5-55dc-969d-255698c62163', 'In the anatomy lab a pin marked the estradiol on the demonstration specimen.', 'A lab pin showed where the main ovarian estrogen sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了雌二醇。'),
  ('62d1cf45-6708-5995-a14f-fdcc3c196968', 'The printed handover sheet kept the renin on the first line.', 'The paper handover put a kidney enzyme that starts the angiotensin cascade at the top of the list.', '打印的交接单把肾素放在第一行。'),
  ('87e6de5b-61b7-5a68-ad0c-702d4038f4e1', 'Her revision card grouped the calcium with two nearby classroom terms.', 'The revision card put the mineral of bone, muscle contraction, and clotting together with two neighboring class words.', '她的复习卡把钙和两个邻近的课堂词放在一组。'),
  ('f6da7732-1b51-5056-b37d-c532dc8bc312', 'The consultant summary named the pregnancy and then restated it in plain words.', 'The senior first said the state of carrying a developing fetus, then repeated the idea in everyday language.', '顾问医师先点出妊娠，再用白话复述一遍。'),
  ('a16f8796-8ee6-5467-9bc1-3ba262a1013e', 'The intern added phosphorus to the problem list after morning teaching.', 'After the teaching round, the intern listed an essential mineral in bone and energy metabolism among the problems.', '晨间带教后，实习医生把磷写进了问题列表。'),
  ('9f40f27e-ef79-539c-ac18-c0c2cf09d197', 'On the ward round the registrar paused so juniors could name the malatonin.', 'During rounds the senior stopped and asked the juniors to name a pineal sleep hormone (textbook spelling of melatonin).', '查房时，高年资住院医师停下来，让低年资医生说出褪黑素。'),
  ('e0e021d5-f0ef-55bd-bf4d-c8a26f2d4edb', 'The lecture slide highlighted the puberty next to a simpler neighboring term.', 'The classroom slide put the period of becoming sexually mature beside a plainer nearby word.', '课堂幻灯把青春期标在一个更浅的邻近词旁边。'),
  ('7c37fe54-6ae0-5257-aa06-4504d35a84fe', 'The first chapter figure was a simple diagram of the circadian rhythms.', 'The opening figure was a plain diagram of about-24-hour biologic cycles.', '该章第一张图就是昼夜节律的简单示意图。'),
  ('ba996c8b-3460-570d-83e1-6a4690f6441f', 'The textbook figure labels the parathyroid beside the neighboring tissue.', 'The printed figure marks the small glands that raise blood calcium via PTH next to the nearby tissue.', '教材插图把甲状旁腺标在邻近组织旁边。'),
  ('1079510d-caa0-539d-8600-203060cac002', 'The textbook treats the parathyroid hormone as core vocabulary, not extra trivia.', 'The book treats the hormone that raises blood calcium as a must-know classroom term, not spare trivia.', '教材把甲状旁腺激素当作核心课堂词，而不是附加冷知识。'),
  ('45979cf0-ee1f-5c30-8b11-17cf6af3602d', 'The attending asked whether the process was truly pineal in this patient.', 'The consultant checked that the process really was relating to the pineal gland here.', '主治医师问：这个过程在该患者身上是否真的是松果体的。'),
  ('92631926-212c-503a-a955-1d74e46d9723', 'The progress note mentioned the calcitonin in one plain line.', 'The ward note used one simple line to record a thyroid hormone that lowers blood calcium.', '病程记录用一句平实的话写到了降钙素。'),
  ('57c56cbd-d44f-54f5-9e34-c34e8a606611', 'After history taking, the student wrote the sphenoid under current problems.', 'Once the history was finished, the student listed the bone at the base of the skull housing the pituitary fossa with the current problems.', '问完病史后，学生把蝶骨写在目前问题下面。'),
  ('5bd93756-a23b-5cd2-ae5f-93d49c544770', 'The tutorial pair had to point to the anterior lobe and say it aloud.', 'Each pair pointed to the front lobe of the pituitary; adenohypophysis and said the words out loud.', '小组课上，两人要指出前叶并大声读出来。'),
  ('54bae21c-761a-58db-8870-cd8fdf4a35eb', 'A short teaching note introduced the primary aldosteronism before any later complications.', 'The teaching note named excess aldosterone from the adrenal itself first, before later complications.', '短教学笔记先介绍原发性醛固酮增多症，再谈后续并发症。'),
  ('dfdc2269-2a03-5aa0-afe7-18382744f75c', 'In the tutorial, each pair had to explain the adenohypophysis in one spoken sentence.', 'Tutorial pairs had to say the anterior pituitary out loud in a single sentence.', '小组课上，每两人要用一句话口头解释腺垂体。'),
  ('9d08a329-8570-5fcf-a1e7-afb26192b1ed', 'The teaching conference used one slide only for the posterior lobe.', 'The conference reserved a whole slide for the back lobe of the pituitary; neurohypophysis.', '教学讨论会单独用一张幻灯讲后叶。'),
  ('40b7e1a8-a361-5e39-b015-8680e78759ee', 'Night handover listed the pheochromocytoma before the overnight plan.', 'The night team named a catecholamine-secreting adrenal medullary tumor first, then said what to do overnight.', '夜班交接时先提到嗜铬细胞瘤，再讲夜间计划。'),
  ('c1fb3b6b-813a-5070-9926-c9994f4a6b10', 'The chapter margin lists the neurohypophysis with other core classroom words.', 'The side note groups the posterior pituitary with the other must-know terms.', '章节页边把神经垂体和其他课堂核心词列在一起。'),
  ('ea3f836d-1fac-52ee-a91d-d66a434f80a3', 'Bedside teaching returned to the gigantism whenever the finding came up.', 'At the bedside the teacher kept coming back to excess growth hormone before epiphyseal closure when that finding appeared.', '床旁带教时，一碰到这个发现就会回到巨人症。'),
  ('10954a04-e4e9-55a4-8eff-9cd11b710985', 'The case stem named the hypothalamus before asking what to do next.', 'The exam-style stem first named the basal brain region that controls pituitary and autonomic function, then asked for the next step.', '病例题干先写出下丘脑，再问下一步怎么做。'),
  ('3b3c4d5c-44c2-5300-8f4a-822e1222e5c1', 'The tutor wrote the acromegaly on the board and circled the classroom sense.', 'On the board the tutor wrote excess growth hormone after epiphyseal closure and marked the classroom meaning.', '老师把肢端肥大症写在黑板上，并圈出课堂义。'),
  ('be7e4be2-5b69-5a08-8824-4596f9544fcc', 'After examination the sign was documented as mammary.', 'Once the exam was done, the team wrote that the finding was relating to the breast.', '查体结束后，记录把该体征写成乳房的。'),
  ('053b857d-7e41-5dfc-b37a-78817d8112ba', 'The first chapter figure was a simple diagram of the diabetes insipidus.', 'The opening figure was a plain diagram of large volumes of dilute urine from ADH lack or resistance.', '该章第一张图就是尿崩症的简单示意图。'),
  ('23ec7d7f-6d2d-5933-b7e0-4703430e333f', 'The textbook warns not to write antidiuretic unless the evidence actually fits.', 'The book says use this word only when the finding truly is reducing urine volume, as ADH does.', '教材提醒：证据对得上时才能写抗利尿的。'),
  ('b975efad-cb1e-5986-b9d6-201dd234429f', 'The printed handover sheet kept the hyperthyroidism on the first line.', 'The paper handover put excess thyroid hormone action at the top of the list.', '打印的交接单把甲状腺功能亢进放在第一行。'),
  ('7c7dc686-fcb0-5b62-bb47-0a2664a8e153', 'The attending asked whether the process was truly uterine in this patient.', 'The consultant checked that the process really was relating to the uterus here.', '主治医师问：这个过程在该患者身上是否真的是子宫的。'),
  ('782dca7d-8543-55b6-a719-d7fff6f348e4', 'The consultant summary named the isthmus and then restated it in plain words.', 'The senior first said a narrow connection, such as the thyroid isthmus, then repeated the idea in everyday language.', '顾问医师先点出峡，再用白话复述一遍。'),
  ('6918936d-c343-53dc-a803-3e6cd5884790', 'The intern added hyperparathyroidism to the problem list after morning teaching.', 'After the teaching round, the intern listed excess parathyroid hormone with high calcium among the problems.', '晨间带教后，实习医生把甲状旁腺功能亢进写进了问题列表。'),
  ('6810143c-7754-5dee-8405-c42804afc042', 'On the ward round the registrar paused so juniors could name the thyroxine.', 'During rounds the senior stopped and asked the juniors to name T4, the main circulating thyroid hormone.', '查房时，高年资住院医师停下来，让低年资医生说出甲状腺素。'),
  ('b1b2d93f-125b-59b9-945f-b6c8da68ffa6', 'The lecture slide highlighted the hypoparathyroidism next to a simpler neighboring term.', 'The classroom slide put too little parathyroid hormone with low calcium beside a plainer nearby word.', '课堂幻灯把甲状旁腺功能减退标在一个更浅的邻近词旁边。'),
  ('e81f5e53-5f45-5143-9a48-de6699239203', 'A one-paragraph case opened by naming the triiodothyronine before later findings.', 'The short case first named T3, the more active thyroid hormone, then listed what came next.', '短病例开头先写出三碘甲腺原氨酸，再写后面的发现。'),
  ('a3deb3ae-6bfa-5208-af88-42230389ed19', 'The textbook figure labels the hyperglycemia beside the neighboring tissue.', 'The printed figure marks abnormally high blood glucose next to the nearby tissue.', '教材插图把高血糖标在邻近组织旁边。'),
  ('1547939d-b5b6-5b9b-ba34-b1a28b1dc4c0', 'In class the tutor pointed to the homeostasis on the wall chart.', 'The tutor used the wall chart and pointed to the maintenance of a stable internal environment.', '课堂上，老师指着墙上的图讲解稳态。'),
  ('59c06fff-d1c5-506d-bcc9-37baa9b43f63', 'The registrar said the wording should stay medullar in the discharge line.', 'The senior wanted the discharge line to keep the sense relating to a medulla (textbook form of medullary).', '住院总医师说出院小结仍应写成髓质的。'),
  ('51ab90f5-7c23-585c-a38e-b92c94ec6c5c', 'The progress note mentioned the corticosteroid in one plain line.', 'The ward note used one simple line to record an adrenal-type steroid used to suppress inflammation.', '病程记录用一句平实的话写到了糖皮质激素。'),
  ('079ea698-d0cc-5238-b771-9c6ab9385232', 'After history taking, the student wrote the glucose under current problems.', 'Once the history was finished, the student listed the main blood sugar used by tissues with the current problems.', '问完病史后，学生把葡萄糖写在目前问题下面。'),
  ('bc4de617-cfca-516c-8ab2-8d9424f50403', 'The attending asked whether this really was the glucocorticoid or a looser bedside word.', 'The consultant checked that the team meant an adrenal steroid that raises glucose and suppresses inflammation, not a vaguer everyday word.', '主治医师追问：这里是不是糖皮质激素，还是只是更松的床旁说法。'),
  ('e0394683-14b5-569a-8528-11b6abe3d55d', 'A labelled classroom slide showed the ketoacidosis without extra commentary.', 'The teaching slide simply marked high ketones with metabolic acidosis, usually in type 1 diabetes and left the rest for discussion.', '一张带标注的课堂幻灯只标出酮症酸中毒，没有再加解释。'),
  ('9a040d2d-7c13-5c70-8f47-a93e69b6cc0e', 'In the tutorial, each pair had to explain the cortisol in one spoken sentence.', 'Tutorial pairs had to say the main glucocorticoid of the adrenal cortex out loud in a single sentence.', '小组课上，每两人要用一句话口头解释皮质醇。'),
  ('1876c708-ac19-5fb7-b6c4-fe3161153dd3', 'On rounds the registrar asked for the everyday function of the endemic goiter.', 'On rounds the senior asked what goiter common in an iodine-deficient region does in ordinary words.', '查房时，住院医师问地方性甲状腺肿日常起什么作用。'),
  ('f11be7bf-f1b0-5f38-9506-bf73bc463602', 'Night handover listed the mineralocorticoid before the overnight plan.', 'The night team named an adrenal steroid that retains sodium, such as aldosterone first, then said what to do overnight.', '夜班交接时先提到盐皮质激素，再讲夜间计划。'),
  ('6df1f1ef-11e7-5eb4-b543-9afd4b5019fd', 'The chapter margin lists the aldosterone with other core classroom words.', 'The side note groups the mineralocorticoid that retains sodium with the other must-know terms.', '章节页边把醛固酮和其他课堂核心词列在一起。'),
  ('215ab755-41d3-531a-8b17-0d27911e16f3', 'The handover sheet kept the nodular goiter on its own line.', 'The handover kept an enlarged thyroid containing nodules on a separate line.', '交接单给结节性甲状腺肿单独留了一行。'),
  ('41a9ed0c-ba50-556c-94f6-e1bf890bcb38', 'The case stem named the bruit before asking what to do next.', 'The exam-style stem first named an abnormal vascular sound heard with a stethoscope, then asked for the next step.', '病例题干先写出杂音，再问下一步怎么做。'),
  ('4b547585-60c9-56f4-ae11-542bc1866c9d', 'The tutor wrote the myxedema on the board and circled the classroom sense.', 'On the board the tutor wrote severe hypothyroidism with doughy swelling and marked the classroom meaning.', '老师把黏液性水肿写在黑板上，并圈出课堂义。'),
  ('ff69183f-46c4-50f0-b7ec-a9b8e5f3ad03', 'The admission note placed the ptosis among the early working problems.', 'The first ward note included drooping of an organ or eyelid in the early problem list.', '入院记录把下垂写进了初步问题。'),
  ('feefd7e2-e209-5d6a-89ef-dc43502116fa', 'The classroom quiz asked students to recognise the neuron from a short stem.', 'The quiz used a short stem and asked students to recognise the electrically signaling cell of the nervous system.', '随堂测验用一小段题干，让学生认出神经元。'),
  ('6c2602bd-99fa-55c7-ac71-c59658e01ae1', 'In the anatomy lab a pin marked the diencephalon on the demonstration specimen.', 'A lab pin showed where the brain region including thalamus and hypothalamus sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了间脑。'),
  ('a492000c-a567-578c-a96c-19a880483bd0', 'The printed handover sheet kept the pons on the first line.', 'The paper handover put the brainstem bulge between midbrain and medulla at the top of the list.', '打印的交接单把脑桥放在第一行。'),
  ('61cf826a-d9c2-5014-8b41-08f783b4325a', 'Her revision card grouped the neurology with two nearby classroom terms.', 'The revision card put the study of the nervous system and its diseases together with two neighboring class words.', '她的复习卡把神经病学和两个邻近的课堂词放在一组。'),
  ('4efd4bff-ff57-50cc-bc05-2c3e7a0b1abb', 'The consultant summary named the cerebellum and then restated it in plain words.', 'The senior first said the hindbrain structure that coordinates movement, then repeated the idea in everyday language.', '顾问医师先点出小脑，再用白话复述一遍。'),
  ('f65085aa-acf4-51aa-9090-99a7c6b676b7', 'The intern added acetylcholine to the problem list after morning teaching.', 'After the teaching round, the intern listed a neurotransmitter at neuromuscular and many autonomic synapses among the problems.', '晨间带教后，实习医生把乙酰胆碱写进了问题列表。'),
  ('9ff63c44-3af9-50fb-8f73-b598c93b0f43', 'The case note named the brain stem before describing what happened next.', 'The note first named midbrain, pons, and medulla connecting brain and cord, then said what followed.', '病历先写出脑干，再写接下来发生了什么。'),
  ('45f2392b-53da-58fd-b1ca-c8d2b4f6fe4f', 'After examination the sign was documented as efferent.', 'Once the exam was done, the team wrote that the finding was carrying impulses away from a center.', '查体结束后，记录把该体征写成传出的。'),
  ('018e223a-68b9-50e3-b07c-63a206937463', 'The first chapter figure was a simple diagram of the medulla oblongata.', 'The opening figure was a plain diagram of the lowest brainstem, continuous with the spinal cord.', '该章第一张图就是延髓的简单示意图。'),
  ('618fc82b-768a-5851-b4ad-c361d4c4f6b3', 'The textbook warns not to write afferent unless the evidence actually fits.', 'The book says use this word only when the finding truly is carrying impulses toward a center.', '教材提醒：证据对得上时才能写传入的。'),
  ('377d8182-10ba-5721-9a50-a38b0184c64f', 'In class the tutor pointed to the meninx on the wall chart.', 'The tutor used the wall chart and pointed to one of the meninges covering brain or cord.', '课堂上，老师指着墙上的图讲解脑膜。'),
  ('f7395ad1-a29d-5272-8116-7e13bcc16b3a', 'The attending asked whether the process was truly parasympathetic in this patient.', 'The consultant checked that the process really was relating to the rest-and-digest autonomic division here.', '主治医师问：这个过程在该患者身上是否真的是副交感的。'),
  ('fc1db592-75a7-5127-8b60-f43c45c3ae58', 'The handover sheet kept the cauda equina on its own line.', 'The handover kept the bundle of lumbar and sacral roots below the cord on a separate line.', '交接单给马尾单独留了一行。'),
  ('f8b94828-74e5-5850-9bf5-26d657973177', 'After history taking, the student wrote the dura under current problems.', 'Once the history was finished, the student listed the tough outer meninx; dura mater with the current problems.', '问完病史后，学生把硬膜写在目前问题下面。'),
  ('617e059d-53e2-59b6-a8b6-8112b561efcb', 'The quiz asked which finding should be called sympathetic.', 'The quiz wanted the finding that is honestly relating to the fight-or-flight autonomic division.', '测验问：哪个发现才该写成交感的。'),
  ('051b6370-e95e-58df-a657-708892ed50e6', 'A labelled classroom slide showed the mater without extra commentary.', 'The teaching slide simply marked mater in dura/pia/arachnoid mater, a meningeal layer and left the rest for discussion.', '一张带标注的课堂幻灯只标出膜（脑脊膜），没有再加解释。'),
  ('d1e5c68a-c24f-5258-8c12-ae479e937184', 'In the tutorial, each pair had to explain the arachnoid in one spoken sentence.', 'Tutorial pairs had to say the middle meningeal layer out loud in a single sentence.', '小组课上，每两人要用一句话口头解释蛛网膜。'),
  ('dd33f64d-2c5d-5511-b50d-1b3a46dcc7ae', 'At the teaching conference the film was used to locate the ganglion.', 'The teaching meeting used the image so students could find a cluster of nerve-cell bodies outside the CNS.', '教学读片会上，用这张片子让学生找出神经节。'),
  ('557e3685-43bb-59a2-b330-16dec67fb13e', 'Her revision list put the pia mater with two neighboring system terms.', 'The revision list grouped the delicate inner meninx on the brain and cord surface with two nearby system terms.', '她的复习表把软膜和两个邻近系统词放在一起。'),
  ('2c1eb157-684e-57f2-878a-7e30e3aa6362', 'The chapter margin lists the plexus with other core classroom words.', 'The side note groups a network of nerves or vessels with the other must-know terms.', '章节页边把丛和其他课堂核心词列在一起。'),
  ('d9d5c165-ede2-5d48-a18e-ddc656d844bb', 'A margin gloss repeats the lumbar puncture in smaller type beside the main paragraph.', 'The margin repeats needle sampling of CSF in the lumbar sac in smaller type next to the main paragraph.', '页边用小字在正文旁重复写出腰椎穿刺。'),
  ('01513836-f4ef-5deb-beff-5059182f7265', 'The case stem named the dendrite before asking what to do next.', 'The exam-style stem first named the branching process that receives synaptic input, then asked for the next step.', '病例题干先写出树突，再问下一步怎么做。'),
  ('660ef609-5cff-5d15-b44f-2357849ef978', 'The case note named the electrical charge before describing what happened next.', 'The note first named the charged state that underlies nerve action potentials, then said what followed.', '病历先写出电荷，再写接下来发生了什么。'),
  ('560725b5-5ff6-54ec-88bc-55a04ae33034', 'The admission note placed the axon among the early working problems.', 'The first ward note included the long process that carries a nerve impulse away in the early problem list.', '入院记录把轴突写进了初步问题。'),
  ('b4049f08-da7e-5627-8d0e-9de12527c710', 'The classroom quiz asked students to recognise the myelin from a short stem.', 'The quiz used a short stem and asked students to recognise the insulating sheath around many axons.', '随堂测验用一小段题干，让学生认出髓鞘质。'),
  ('aaf39cba-1b55-5dc2-907f-6d90811067b7', 'In the anatomy lab a pin marked the neurilemma on the demonstration specimen.', 'A lab pin showed where the Schwann-cell sheath around a peripheral axon sat on the demonstration specimen.', '解剖实验室里，标本上的钉子标出了神经膜。'),
  ('4da98763-9a83-5dc1-98de-521ca876da85', 'The printed handover sheet kept the synapse on the first line.', 'The paper handover put the junction where one neuron signals another at the top of the list.', '打印的交接单把突触放在第一行。'),
  ('297920bd-f719-57f9-955d-f57c2276c23d', 'The wall chart boxed the white matter so students could find it quickly.', 'The wall chart put a box around CNS tissue rich in myelinated axons to make it easy to spot.', '墙上的图给白质加了框，方便学生快速找到。'),
  ('834da682-e5e7-5bc4-b547-d30a8ce07211', 'The handover sheet kept the gray matter on its own line.', 'The handover kept CNS tissue rich in cell bodies on a separate line.', '交接单给灰质单独留了一行。'),
  ('7d30ee10-d652-59a7-8246-6eceb9b2b5d3', 'The intern added neurotransmitter to the problem list after morning teaching.', 'After the teaching round, the intern listed a chemical signal released at a synapse among the problems.', '晨间带教后，实习医生把神经递质写进了问题列表。'),
  ('dd3d89b8-3556-59ff-958d-08695057883a', 'On the ward round the registrar paused so juniors could name the neuroglia.', 'During rounds the senior stopped and asked the juniors to name the supporting cells of the nervous system.', '查房时，高年资住院医师停下来，让低年资医生说出神经胶质。'),
  ('93175881-ff10-5e97-a2cf-4b1392fb838d', 'The lecture slide highlighted the astrocyte next to a simpler neighboring term.', 'The classroom slide put a star-shaped glial cell of the CNS beside a plainer nearby word.', '课堂幻灯把星形胶质细胞标在一个更浅的邻近词旁边。'),
  ('ac3ec2af-c7be-5e4d-a639-ae538e6dde10', 'A one-paragraph case opened by naming the glioma before later findings.', 'The short case first named a tumor of glial cells, then listed what came next.', '短病例开头先写出胶质瘤，再写后面的发现。'),
  ('a46c6749-f2a3-5779-9b0f-01890c4eaee9', 'The textbook figure labels the microglia beside the neighboring tissue.', 'The printed figure marks the resident immune cells of the CNS next to the nearby tissue.', '教材插图把小胶质细胞标在邻近组织旁边。'),
  ('d8ec1497-dc8d-5009-a42f-f754240494fb', 'In class the tutor pointed to the oligodendroglia on the wall chart.', 'The tutor used the wall chart and pointed to CNS cells that form myelin.', '课堂上，老师指着墙上的图讲解少突胶质细胞。'),
  ('2925a072-ddd6-5b46-8bfe-23e613300f25', 'In the skills lab students had to identify the cerebrum on a model.', 'Lab practice asked students to find the large paired hemispheres of the brain on the model.', '技能实验室里，学生要在模型上认出大脑。'),
  ('d2e94e1a-45fe-5180-83ab-7c731b897128', 'The progress note mentioned the convolution in one plain line.', 'The ward note used one simple line to record a gyrus; a fold of the cerebral cortex.', '病程记录用一句平实的话写到了脑回。'),
  ('aea12f5d-8ed5-58c8-af38-9c5be9c55738', 'The lecture placed the peripheral nervous system next to related classroom structures.', 'The lecture sat nerves and ganglia outside the brain and cord beside related classroom structures.', '讲课把周围神经系统放在相关课堂结构旁边。'),
  ('cb1165ca-75c2-58f4-ad85-8e463d3c8bf7', 'The case note named the autonomic nervous system before describing what happened next.', 'The note first named the involuntary visceral motor system, then said what followed.', '病历先写出自主神经系统，再写接下来发生了什么。'),
  ('1f244ab9-19ed-5bd8-9c2a-81508c14bb07', 'Students had to explain the visceral nervous system in one plain sentence of their own.', 'Each student had to say the nerves supplying internal organs in one ordinary sentence.', '学生要用自己的一句白话解释内脏神经系统。'),
  ('8852fad9-485c-534b-9533-e640c6b3059b', 'In the tutorial, each pair had to explain the groove in one spoken sentence.', 'Tutorial pairs had to say a shallow furrow on a bone or organ surface out loud in a single sentence.', '小组课上，每两人要用一句话口头解释沟。'),
  ('4a27dba8-4656-5f6d-a826-e686addc8448', 'At the teaching conference the film was used to locate the fissure.', 'The teaching meeting used the image so students could find a deeper cleft, as between cerebral hemispheres.', '教学读片会上，用这张片子让学生找出裂。'),
  ('20ae6df3-4f73-5676-8fc9-bb5bf9cbc6bc', 'Night handover listed the sulcus before the overnight plan.', 'The night team named a groove between gyri of the cortex first, then said what to do overnight.', '夜班交接时先提到沟，再讲夜间计划。'),
  ('530e5656-4263-501a-8e28-d066a1e3ebbf', 'The chapter margin lists the thalamus with other core classroom words.', 'The side note groups the diencephalic relay for sensory pathways to cortex with the other must-know terms.', '章节页边把丘脑和其他课堂核心词列在一起。')
) as v(id, context_sentence, plain_english_paraphrase, sentence_translation_zh)
where c.id = v.id::uuid;

commit;

